static const char s_src_args[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# args.mx - command-line argument parser (core/)\n# Usage:\n#   importx args\n#   let p = newx args.ArgParser(\"mytool\", \"Tool description\")\n#   p.add_flag(\"verbose\", \"v\", \"Enable verbose logging\")\n#   p.add_opt(\"output\", \"o\", \"out.txt\", \"Output file path\")\n#   p.add_arg(\"input\", \"Input file\")\n#   let res = p.parse(args.get_args())\n\nimportx string\nimportx dict\n\nclassx ArgParser {\n    let prog = \"\"\n    let description = \"\"\n    let _flags = nullx        # dict of name -> [short, help]\n    let _opts = nullx         # dict of name -> [short, default, help]\n    let _pos_defs = []        # array of [name, help]\n    let _results = nullx      # dict of name -> val\n    let _positionals = []     # parsed positional values\n\n    func init(prog, description) {\n        this.prog = prog\n        this.description = description\n        this._flags = newx dict.Dict()\n        this._opts = newx dict.Dict()\n        this._results = newx dict.Dict()\n        this._positionals = []\n        this._pos_defs = []\n    }\n\n    func add_flag(name, short_name, help_text) {\n        this._flags.set(name, [short_name, help_text])\n        this._results.set(name, false)\n        return this\n    }\n\n    func add_opt(name, short_name, default_val, help_text) {\n        this._opts.set(name, [short_name, default_val, help_text])\n        this._results.set(name, default_val)\n        return this\n    }\n\n    func add_arg(name, help_text) {\n        this._pos_defs = this._pos_defs + [[name, help_text]]\n        return this\n    }\n\n    func _find_flag_by_short(s) {\n        for k in this._flags.keys {\n            let meta = this._flags.get(k)\n            if meta[0] == s {\n                return k\n            }\n        }\n        return nullx\n    }\n\n    func _find_opt_by_short(s) {\n        for k in this._opts.keys {\n            let meta = this._opts.get(k)\n            if meta[0] == s {\n                return k\n            }\n        }\n        return nullx\n    }\n\n    func parse(argv) {\n        let i = 0\n        let pos_idx = 0\n        this._positionals = []\n\n        while i < len(argv) {\n            let arg = argv[i]\n            if string.starts_with(arg, \"--\") {\n                let key = string.substr(arg, 2, len(arg))\n                let eq_pos = string.index_of(key, \"=\")\n                if eq_pos >= 0 {\n                    let opt_name = string.substr(key, 0, eq_pos)\n                    let opt_val = string.substr(key, eq_pos + 1, len(key))\n                    if this._opts.has(opt_name) {\n                        this._results.set(opt_name, opt_val)\n                    } else if this._flags.has(opt_name) {\n                        this._results.set(opt_name, opt_val == \"true\" || opt_val == \"1\")\n                    }\n                } else {\n                    if this._flags.has(key) {\n                        this._results.set(key, true)\n                    } else if this._opts.has(key) {\n                        if i + 1 < len(argv) {\n                            i = i + 1\n                            this._results.set(key, argv[i])\n                        }\n                    }\n                }\n            } else if string.starts_with(arg, \"-\") && len(arg) > 1 {\n                let sh = string.substr(arg, 1, 2)\n                let flag_name = this._find_flag_by_short(sh)\n                if flag_name != nullx {\n                    this._results.set(flag_name, true)\n                } else {\n                    let opt_name = this._find_opt_by_short(sh)\n                    if opt_name != nullx {\n                        if len(arg) > 2 {\n                            this._results.set(opt_name, string.substr(arg, 2, len(arg)))\n                        } else if i + 1 < len(argv) {\n                            i = i + 1\n                            this._results.set(opt_name, argv[i])\n                        }\n                    }\n                }\n            } else {\n                this._positionals = this._positionals + [arg]\n                if pos_idx < len(this._pos_defs) {\n                    let def_name = this._pos_defs[pos_idx][0]\n                    this._results.set(def_name, arg)\n                    pos_idx = pos_idx + 1\n                }\n            }\n            i = i + 1\n        }\n        return this\n    }\n\n    func get(name) {\n        if this._results.has(name) {\n            return this._results.get(name)\n        }\n        return nullx\n    }\n\n    func has(name) {\n        if this._results.has(name) {\n            let v = this._results.get(name)\n            if v == true {\n                return true\n            }\n            return v != nullx && v != false && v != \"\"\n        }\n        return false\n    }\n\n    func positionals() {\n        return this._positionals\n    }\n\n    func help() {\n        let lines = []\n        lines = lines + [\"Usage: \" + this.prog + \" [options]\"]\n        if this.description != \"\" {\n            lines = lines + [this.description]\n        }\n        lines = lines + [\"Options:\"]\n        for k in this._flags.keys {\n            let meta = this._flags.get(k)\n            let s = meta[0]\n            let h = meta[1]\n            let prefix = \"  --\" + k\n            if s != \"\" {\n                prefix = prefix + \", -\" + s\n            }\n            lines = lines + [prefix + \" : \" + h]\n        }\n        for k in this._opts.keys {\n            let meta = this._opts.get(k)\n            let s = meta[0]\n            let def_val = meta[1]\n            let h = meta[2]\n            let prefix = \"  --\" + k + \" <val>\"\n            if s != \"\" {\n                prefix = prefix + \", -\" + s + \" <val>\"\n            }\n            lines = lines + [prefix + \" : \" + h + \" (default: \" + def_val + \")\"]\n        }\n        return string.join(lines, \"\\n\")\n    }\n}\n\nfunc get_args() {\n    return sys_args()\n}\n\nfunc create_parser(prog, desc) {\n    return newx ArgParser(prog, desc)\n}\n";

