static const char s_src_arrayfull[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# arrayfull.mx - full array toolkit (replaces array.mx)\n# Builders return NEW arrays; swap() mutates in place.\n\nfunc is_empty(arr) {\n    return len(arr) == 0\n}\n\nfunc first(arr) {\n    if len(arr) == 0 {\n        return nullx\n    }\n    return arr[0]\n}\n\nfunc last(arr) {\n    if len(arr) == 0 {\n        return nullx\n    }\n    return arr[len(arr) - 1]\n}\n\nfunc copy(arr) {\n    return arr + []\n}\n\nfunc fill(v, n) {\n    let out = []\n    let i = 0\n    while i < n {\n        out = out + [v]\n        i = i + 1\n    }\n    return out\n}\n\nfunc map(arr, fn) {\n    let out = []\n    for x in arr {\n        out = out + [fn(x)]\n    }\n    return out\n}\n\nfunc filter(arr, fn) {\n    let out = []\n    for x in arr {\n        if fn(x) {\n            out = out + [x]\n        }\n    }\n    return out\n}\n\nfunc reduce(arr, fn, init) {\n    let acc = init\n    for x in arr {\n        acc = fn(acc, x)\n    }\n    return acc\n}\n\nfunc every(arr, fn) {\n    for x in arr {\n        if !fn(x) {\n            return false\n        }\n    }\n    return true\n}\n\nfunc some(arr, fn) {\n    for x in arr {\n        if fn(x) {\n            return true\n        }\n    }\n    return false\n}\n\nfunc count_where(arr, fn) {\n    let n = 0\n    for x in arr {\n        if fn(x) {\n            n = n + 1\n        }\n    }\n    return n\n}\n\nfunc find(arr, fn) {\n    for x in arr {\n        if fn(x) {\n            return x\n        }\n    }\n    return nullx\n}\n\nfunc find_index(arr, fn) {\n    let i = 0\n    while i < len(arr) {\n        if fn(arr[i]) {\n            return i\n        }\n        i = i + 1\n    }\n    return -1\n}\n\n# search by value (== is deep for arrays); named to never clash with string.index_of\nfunc arr_index_of(arr, val) {\n    let i = 0\n    while i < len(arr) {\n        if arr[i] == val {\n            return i\n        }\n        i = i + 1\n    }\n    return -1\n}\n\nfunc includes(arr, val) {\n    return arr_index_of(arr, val) != -1\n}\n\nfunc sum(arr) {\n    let s = 0\n    for x in arr {\n        s = s + x\n    }\n    return s\n}\n\nfunc min_of(arr) {\n    if len(arr) == 0 {\n        return nullx\n    }\n    let m = arr[0]\n    let i = 1\n    while i < len(arr) {\n        if arr[i] < m {\n            m = arr[i]\n        }\n        i = i + 1\n    }\n    return m\n}\n\nfunc max_of(arr) {\n    if len(arr) == 0 {\n        return nullx\n    }\n    let m = arr[0]\n    let i = 1\n    while i < len(arr) {\n        if arr[i] > m {\n            m = arr[i]\n        }\n        i = i + 1\n    }\n    return m\n}\n\nfunc reversed(arr) {\n    let out = []\n    let i = len(arr) - 1\n    while i >= 0 {\n        out = out + [arr[i]]\n        i = i - 1\n    }\n    return out\n}\n\nfunc slice(arr, start, end) {\n    let out = []\n    if start < 0 {\n        start = 0\n    }\n    if end > len(arr) {\n        end = len(arr)\n    }\n    let i = start\n    while i < end {\n        out = out + [arr[i]]\n        i = i + 1\n    }\n    return out\n}\n\nfunc take(arr, n) {\n    return slice(arr, 0, n)\n}\n\nfunc drop(arr, n) {\n    return slice(arr, n, len(arr))\n}\n\nfunc concat(a, b) {\n    return a + b\n}\n\nfunc push(arr, v) {\n    return arr + [v]\n}\n\n# -> [array_without_last, last_value]; [same_array, nullx] when empty\nfunc pop(arr) {\n    if len(arr) == 0 {\n        return [arr, nullx]\n    }\n    return [slice(arr, 0, len(arr) - 1), arr[len(arr) - 1]]\n}\n\nfunc unshift(arr, v) {\n    return [v] + arr\n}\n\n# -> [array_without_first, first_value]\nfunc shift(arr) {\n    if len(arr) == 0 {\n        return [arr, nullx]\n    }\n    return [slice(arr, 1, len(arr)), arr[0]]\n}\n\nfunc insert_at(arr, i, v) {\n    if i < 0 {\n        i = 0\n    }\n    if i > len(arr) {\n        i = len(arr)\n    }\n    let out = slice(arr, 0, i)\n    out = out + [v]\n    return out + slice(arr, i, len(arr))\n}\n\nfunc remove_at(arr, i) {\n    if i < 0 || i >= len(arr) {\n        throwx \"remove_at: index out of range\"\n    }\n    return slice(arr, 0, i) + slice(arr, i + 1, len(arr))\n}\n\n# mutates arr in place\nfunc swap(arr, i, j) {\n    if i < 0 || i >= len(arr) || j < 0 || j >= len(arr) {\n        throwx \"swap: index out of range\"\n    }\n    let tmp = arr[i]\n    arr[i] = arr[j]\n    arr[j] = tmp\n    return arr\n}\n\nfunc flatten(arr) {\n    let out = []\n    for x in arr {\n        if typeofx(x) == \"array\" {\n            out = out + x\n        } else {\n            out = out + [x]\n        }\n    }\n    return out\n}\n\nfunc unique(arr) {\n    let out = []\n    for x in arr {\n        if !includes(out, x) {\n            out = out + [x]\n        }\n    }\n    return out\n}\n\n# -> [[matched], [not_matched]]\nfunc partition(arr, fn) {\n    let yes = []\n    let no = []\n    for x in arr {\n        if fn(x) {\n            yes = yes + [x]\n        } else {\n            no = no + [x]\n        }\n    }\n    return [yes, no]\n}\n\n# cmp(a, b) < 0 means a comes first. Selection sort, not stable.\nfunc sort_by(arr, cmp) {\n    let a = arr + []\n    let i = 0\n    while i < len(a) {\n        let best = i\n        let j = i + 1\n        while j < len(a) {\n            if cmp(a[j], a[best]) < 0 {\n                best = j\n            }\n            j = j + 1\n        }\n        if best != i {\n            let tmp = a[i]\n            a[i] = a[best]\n            a[best] = tmp\n        }\n        i = i + 1\n    }\n    return a\n}\n";

