static const char s_src_assert[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# assert.mx - assertions & test tracking (core/)\n# Failures throw; use Tracker for non-throwing checks.\n# NOTE: delete assert_true/assert_eq from error.mx - they live here now.\n\nfunc assert_true(cond, message) {\n    if !cond {\n        throwx \"assert_true failed: \" + message\n    }\n    return true\n}\n\nfunc assert_false(cond, message) {\n    if cond {\n        throwx \"assert_false failed: \" + message\n    }\n    return true\n}\n\nfunc assert_eq(a, b, message) {\n    if !(a == b) {\n        throwx \"assert_eq failed: \" + message + \" (expected \" + b + \", got \" + a + \")\"\n    }\n    return true\n}\n\nfunc assert_ne(a, b, message) {\n    if a == b {\n        throwx \"assert_ne failed: \" + message + \" (both are \" + a + \")\"\n    }\n    return true\n}\n\nfunc assert_null(v, message) {\n    if v != nullx {\n        throwx \"assert_null failed: \" + message + \" (got \" + v + \")\"\n    }\n    return true\n}\n\nfunc assert_not_null(v, message) {\n    if v == nullx {\n        throwx \"assert_not_null failed: \" + message\n    }\n    return true\n}\n\nfunc assert_between(x, lo, hi, message) {\n    if x < lo || x > hi {\n        throwx \"assert_between failed: \" + message + \" (\" + x + \" not in [\" + lo + \", \" + hi + \"])\"\n    }\n    return true\n}\n\n# fn must throw for this to pass; returns the caught value\nfunc assert_throws(fn, message) {\n    tryx {\n        fn()\n    } catchx(e) {\n        return e\n    }\n    throwx \"assert_throws failed: \" + message + \" (no error was thrown)\"\n}\n\n# fn must NOT throw\nfunc assert_no_throw(fn, message) {\n    tryx {\n        fn()\n    } catchx(e) {\n        throwx \"assert_no_throw failed: \" + message + \" (got: \" + e + \")\"\n    }\n    return true\n}\n\nclassx Tracker {\n    let passed = 0\n    let failed = 0\n    let failures = []\n\n    func check(cond, label) {\n        if cond {\n            this.passed = this.passed + 1\n        } else {\n            this.failed = this.failed + 1\n            this.failures = this.failures + [label]\n        }\n        return cond\n    }\n\n    func check_eq(a, b, label) {\n        return this.check(a == b, label + \" (expected \" + b + \", got \" + a + \")\")\n    }\n\n    func summary() {\n        if this.failed == 0 {\n            printx(\"OK - \" + this.passed + \" check(s) passed\")\n        } else {\n            printx(\"FAILED - \" + this.passed + \" passed, \" + this.failed + \" failed\")\n            for f in this.failures {\n                printx(\"  - \" + f)\n            }\n        }\n        return this.failed == 0\n    }\n}\n";

