static const char s_src_bst[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# bst.mx - binary search tree used as an ordered map (key -> value)\n# Keys must all be the same type (numbers or strings) so < and == work.\n\nclassx BstNode {\n    let key = nullx\n    let val = nullx\n    let left = nullx\n    let right = nullx\n\n    func init(key, val) {\n        this.key = key\n        this.val = val\n    }\n}\n\nclassx BST {\n    let root = nullx\n    let count = 0\n\n    func insert(key, val) {\n        if this.root == nullx {\n            this.root = newx BstNode(key, val)\n            this.count = this.count + 1\n            return this\n        }\n        let cur = this.root\n        while true {\n            if key == cur.key {\n                cur.val = val\n                return this\n            }\n            if key < cur.key {\n                if cur.left == nullx {\n                    cur.left = newx BstNode(key, val)\n                    this.count = this.count + 1\n                    return this\n                }\n                cur = cur.left\n            } else {\n                if cur.right == nullx {\n                    cur.right = newx BstNode(key, val)\n                    this.count = this.count + 1\n                    return this\n                }\n                cur = cur.right\n            }\n        }\n    }\n\n    # nullx when the key is absent (avoid storing nullx values; use has())\n    func get(key) {\n        let cur = this.root\n        while cur != nullx {\n            if key == cur.key {\n                return cur.val\n            }\n            if key < cur.key {\n                cur = cur.left\n            } else {\n                cur = cur.right\n            }\n        }\n        return nullx\n    }\n\n    func get_or_default(key, d) {\n        let cur = this.root\n        while cur != nullx {\n            if key == cur.key {\n                return cur.val\n            }\n            if key < cur.key {\n                cur = cur.left\n            } else {\n                cur = cur.right\n            }\n        }\n        return d\n    }\n\n    func has(key) {\n        let cur = this.root\n        while cur != nullx {\n            if key == cur.key {\n                return true\n            }\n            if key < cur.key {\n                cur = cur.left\n            } else {\n                cur = cur.right\n            }\n        }\n        return false\n    }\n\n    # true if the key existed\n    func remove(key) {\n        if !this.has(key) {\n            return false\n        }\n        this.count = this.count - 1\n        this.root = this._remove(this.root, key)\n        return true\n    }\n\n    func _remove(node, key) {\n        if node == nullx {\n            return nullx\n        }\n        if key < node.key {\n            node.left = this._remove(node.left, key)\n            return node\n        }\n        if key > node.key {\n            node.right = this._remove(node.right, key)\n            return node\n        }\n        # found it\n        if node.left == nullx {\n            return node.right\n        }\n        if node.right == nullx {\n            return node.left\n        }\n        # two children: swap in the successor, then delete it from the right\n        let succ = node.right\n        while succ.left != nullx {\n            succ = succ.left\n        }\n        node.key = succ.key\n        node.val = succ.val\n        node.right = this._remove(node.right, succ.key)\n        return node\n    }\n\n    func min_key() {\n        if this.root == nullx {\n            return nullx\n        }\n        let cur = this.root\n        while cur.left != nullx {\n            cur = cur.left\n        }\n        return cur.key\n    }\n\n    func max_key() {\n        if this.root == nullx {\n            return nullx\n        }\n        let cur = this.root\n        while cur.right != nullx {\n            cur = cur.right\n        }\n        return cur.key\n    }\n\n    func size() {\n        return this.count\n    }\n\n    func is_empty() {\n        return this.count == 0\n    }\n\n    func clear() {\n        this.root = nullx\n        this.count = 0\n    }\n\n    func _inorder_keys(node, acc) {\n        if node == nullx {\n            return acc\n        }\n        acc = this._inorder_keys(node.left, acc)\n        acc = acc + [node.key]\n        acc = this._inorder_keys(node.right, acc)\n        return acc\n    }\n\n    func _inorder_pairs(node, acc) {\n        if node == nullx {\n            return acc\n        }\n        acc = this._inorder_pairs(node.left, acc)\n        acc = acc + [[node.key, node.val]]\n        acc = this._inorder_pairs(node.right, acc)\n        return acc\n    }\n\n    # keys in sorted order\n    func keys() {\n        return this._inorder_keys(this.root, [])\n    }\n\n    # [[key, value], ...] in sorted key order\n    func entries() {\n        return this._inorder_pairs(this.root, [])\n    }\n\n    # values in sorted key order\n    func values() {\n        let out = []\n        for p in this.entries() {\n            out = out + [p[1]]\n        }\n        return out\n    }\n\n    func _height(node) {\n        if node == nullx {\n            return 0\n        }\n        let lh = this._height(node.left)\n        let rh = this._height(node.right)\n        if lh > rh {\n            return lh + 1\n        }\n        return rh + 1\n    }\n\n    # 0 for empty; 1 for a single node\n    func height() {\n        return this._height(this.root)\n    }\n}\n";

