/* ---- Module: buffer (/home/theyad75/Desktop/antmountxlang/shared/stdlib/system/buffer.mx) ---- */
static const char s_src_buffer[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# buffer.mx - binary buffer and byte manipulation (system/)\n# Usage:\n#   importx buffer\n#   let b = buffer.create(10) # 10 zero bytes\n#   b.set(0, 65)              # 'A'\n#   b.get(0)                  # 65\n#   let b2 = buffer.from_string(\"Hello\")\n#   b2.to_hex()               # \"48656c6c6f\"\n#   let b3 = buffer.from_hex(\"48656c6c6f\")\n#   b3.to_string()            # \"Hello\"\n\nimportx string\n\nlet _HEX_CHARS = \"0123456789abcdef\"\n\nclassx Buffer {\n    let _bytes = []\n\n    func init(size_or_bytes) {\n        this._bytes = []\n        if typeofx(size_or_bytes) == \"number\" {\n            let i = 0\n            while i < size_or_bytes {\n                this._bytes = this._bytes + [0]\n                i = i + 1\n            }\n        } else if typeofx(size_or_bytes) == \"array\" {\n            for b in size_or_bytes {\n                this._bytes = this._bytes + [b % 256]\n            }\n        }\n    }\n\n    func get(idx) {\n        if idx < 0 || idx >= len(this._bytes) {\n            throwx \"Buffer index out of range: \" + idx\n        }\n        return this._bytes[idx]\n    }\n\n    func set(idx, byte_val) {\n        if idx < 0 || idx >= len(this._bytes) {\n            throwx \"Buffer index out of range: \" + idx\n        }\n        this._bytes[idx] = byte_val % 256\n        return this\n    }\n\n    func size() {\n        return len(this._bytes)\n    }\n\n    func append(byte_val) {\n        this._bytes = this._bytes + [byte_val % 256]\n        return this\n    }\n\n    func slice(start, end) {\n        let s = start\n        let e = end\n        if s < 0 { s = 0 }\n        if e > len(this._bytes) { e = len(this._bytes) }\n        let sub = []\n        let i = s\n        while i < e {\n            sub = sub + [this._bytes[i]]\n            i = i + 1\n        }\n        return newx Buffer(sub)\n    }\n\n    func to_array() {\n        let copy = []\n        for b in this._bytes {\n            copy = copy + [b]\n        }\n        return copy\n    }\n\n    func to_string() {\n        let s = \"\"\n        for b in this._bytes {\n            s = s + str_chr(b)\n        }\n        return s\n    }\n\n    func to_hex() {\n        let h = \"\"\n        for b in this._bytes {\n            let hi = idiv(b, 16)\n            let lo = b % 16\n            h = h + _HEX_CHARS[hi] + _HEX_CHARS[lo]\n        }\n        return h\n    }\n\n    func write_file(path) {\n        return writex(path, this.to_string())\n    }\n}\n\nfunc create(size) {\n    return newx Buffer(size)\n}\n\nfunc from_string(s) {\n    let bytes = []\n    let i = 0\n    while i < len(s) {\n        bytes = bytes + [str_ord(s[i])]\n        i = i + 1\n    }\n    return newx Buffer(bytes)\n}\n\nfunc from_array(arr) {\n    return newx Buffer(arr)\n}\n\nfunc from_hex(hex_str) {\n    let clean = string.to_lower(hex_str)\n    let bytes = []\n    let i = 0\n    while i < len(clean) {\n        if i + 1 < len(clean) {\n            let hi = string.index_of(_HEX_CHARS, clean[i])\n            let lo = string.index_of(_HEX_CHARS, clean[i + 1])\n            if hi >= 0 && lo >= 0 {\n                bytes = bytes + [(hi * 16) + lo]\n            }\n            i = i + 2\n        } else {\n            i = i + 1\n        }\n    }\n    return newx Buffer(bytes)\n}\n\nfunc read_file(path) {\n    let content = readx(path)\n    return from_string(content)\n}\n";

