static const char s_src_datetime[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# datetime.mx - date and time manipulation and formatting (system/)\n# Usage:\n#   importx datetime\n#   let dt = datetime.now()\n#   dt.iso_format()       # \"2026-10-08T01:13:31\"\n#   dt.format(\"YYYY-MM-DD\") # \"2026-10-08\"\n\nimportx string\n\nfunc is_leap_year(y) {\n    if y % 400 == 0 { return true }\n    if y % 100 == 0 { return false }\n    return y % 4 == 0\n}\n\nfunc days_in_month(y, m) {\n    if m == 2 {\n        if is_leap_year(y) { return 29 }\n        return 28\n    }\n    if m == 4 || m == 6 || m == 9 || m == 11 {\n        return 30\n    }\n    return 31\n}\n\nfunc _pad2(n) {\n    if n < 10 {\n        return \"0\" + n\n    }\n    return \"\" + n\n}\n\nclassx DateTime {\n    let year = 1970\n    let month = 1\n    let day = 1\n    let hour = 0\n    let minute = 0\n    let second = 0\n    let millisecond = 0\n\n    func init(y, m, d, h, mi, s, ms) {\n        this.year = y\n        this.month = m\n        this.day = d\n        this.hour = h\n        this.minute = mi\n        this.second = s\n        if ms == nullx {\n            this.millisecond = 0\n        } else {\n            this.millisecond = ms\n        }\n    }\n\n    func to_timestamp() {\n        # Days from 1970-01-01\n        let y = 1970\n        let days = 0\n        while y < this.year {\n            let add_days = 365\n            if is_leap_year(y) {\n                add_days = 366\n            }\n            days = days + add_days\n            y = y + 1\n        }\n        let m = 1\n        while m < this.month {\n            days = days + days_in_month(this.year, m)\n            m = m + 1\n        }\n        days = days + (this.day - 1)\n        let total_seconds = (days * 86400) + (this.hour * 3600) + (this.minute * 60) + this.second\n        return (total_seconds * 1000) + this.millisecond\n    }\n\n    func iso_format() {\n        return \"\" + this.year + \"-\" + _pad2(this.month) + \"-\" + _pad2(this.day) + \"T\" +\n               _pad2(this.hour) + \":\" + _pad2(this.minute) + \":\" + _pad2(this.second)\n    }\n\n    func format(fmt) {\n        let out = fmt\n        out = string.replace(out, \"YYYY\", \"\" + this.year)\n        out = string.replace(out, \"MM\", _pad2(this.month))\n        out = string.replace(out, \"DD\", _pad2(this.day))\n        out = string.replace(out, \"HH\", _pad2(this.hour))\n        out = string.replace(out, \"mm\", _pad2(this.minute))\n        out = string.replace(out, \"ss\", _pad2(this.second))\n        return out\n    }\n}\n\nfunc from_timestamp(ms) {\n    let total_sec = idiv(ms, 1000)\n    let rem_ms = ms % 1000\n\n    let sec = total_sec % 60\n    let total_min = idiv(total_sec, 60)\n    let min = total_min % 60\n    let total_hours = idiv(total_min, 60)\n    let hour = total_hours % 24\n    let days = idiv(total_hours, 24)\n\n    let y = 1970\n    while true {\n        let diy = 365\n        if is_leap_year(y) {\n            diy = 366\n        }\n        if days >= diy {\n            days = days - diy\n            y = y + 1\n        } else {\n            break\n        }\n    }\n\n    let m = 1\n    while true {\n        let dim = days_in_month(y, m)\n        if days >= dim {\n            days = days - dim\n            m = m + 1\n        } else {\n            break\n        }\n    }\n    let d = days + 1\n\n    return newx DateTime(y, m, d, hour, min, sec, rem_ms)\n}\n\nfunc now() {\n    return from_timestamp(time_now_ms())\n}\n\nfunc create(y, m, d, h, mi, s) {\n    return newx DateTime(y, m, d, h, mi, s, 0)\n}\n";

