static const char s_src_db[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# db.mx - SQLite wrapper for MountX\n# Requires native db_open, db_exec, db_query, db_close in interpreter.py\n\n# Open a database, returns connection id\n# Use \":memory:\" for in-memory DB\nfunc open(path) {\n    return db_open(path)\n}\n\nfunc close(conn) {\n    return db_close(conn)\n}\n\n# Execute INSERT/UPDATE/DELETE/CREATE - returns affected rows\nfunc exec(conn, sql) {\n    return db_exec(conn, sql)\n}\n\nfunc exec_params(conn, sql, params) {\n    return db_exec(conn, sql, params)\n}\n\n# Query SELECT - returns array of rows, each row is an array\nfunc query(conn, sql) {\n    return db_query(conn, sql)\n}\n\nfunc query_params(conn, sql, params) {\n    return db_query(conn, sql, params)\n}\n\n# Helpers\nfunc query_one(conn, sql) {\n    let rows = db_query(conn, sql)\n    if len(rows) == 0 {\n        return null\n    }\n    return rows[0]\n}\n\nfunc query_value(conn, sql) {\n    let row = query_one(conn, sql)\n    if row == null {\n        return null\n    }\n    return row[0]\n}\n";

