/* ---- Module: dict (/home/theyad75/Desktop/antmountxlang/shared/stdlib/data/dict.mx) ---- */
static const char s_src_dict[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# dict.mx - Map/Dictionary replacement using class\n\nclassx Dict {\n    let keys = []\n    let values = []\n\n    func init() {\n        this.keys = []\n        this.values = []\n    }\n\n    func set(k, v) {\n        let i = 0\n        while i < len(this.keys) {\n            if this.keys[i] == k {\n                this.values[i] = v\n                return\n            }\n            i = i + 1\n        }\n        this.keys = this.keys + [k]\n        this.values = this.values + [v]\n    }\n\n    func get(k) {\n        let i = 0\n        while i < len(this.keys) {\n            if this.keys[i] == k {\n                return this.values[i]\n            }\n            i = i + 1\n        }\n        return nullx\n    }\n\n    func has(k) {\n        let i = 0\n        while i < len(this.keys) {\n            if this.keys[i] == k {\n                return true\n            }\n            i = i + 1\n        }\n        return false\n    }\n\n    func remove(k) {\n        let found = false\n        let new_keys = []\n        let new_vals = []\n        let i = 0\n        while i < len(this.keys) {\n            if this.keys[i]!= k {\n                new_keys = new_keys + [this.keys[i]]\n                new_vals = new_vals + [this.values[i]]\n            } else {\n                found = true\n            }\n            i = i + 1\n        }\n        this.keys = new_keys\n        this.values = new_vals\n        return found\n    }\n\n    func size() {\n        return len(this.keys)\n    }\n\n    func clear() {\n        this.keys = []\n        this.values = []\n    }\n}";

