static const char s_src_enum[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# enum.mx - type-safe enumeration helper (core/)\n# Usage:\n#   importx enum\n#   let Status = enum.create([\"PENDING\", \"ACTIVE\", \"COMPLETED\", \"FAILED\"])\n#   let s = Status.get(\"ACTIVE\")  # 1\n#   Status.name_of(1)             # \"ACTIVE\"\n#   Status.has_name(\"PENDING\")    # true\n\nimportx dict\n\nclassx Enum {\n    let _name_to_val = nullx\n    let _val_to_name = nullx\n    let _names_list = []\n    let _values_list = []\n\n    func init(items) {\n        this._name_to_val = newx dict.Dict()\n        this._val_to_name = newx dict.Dict()\n        this._names_list = []\n        this._values_list = []\n\n        let i = 0\n        while i < len(items) {\n            let item = items[i]\n            let k = \"\"\n            let v = i\n            if typeofx(item) == \"array\" && len(item) == 2 {\n                k = item[0]\n                v = item[1]\n            } else {\n                k = \"\" + item\n            }\n            this._name_to_val.set(k, v)\n            this._val_to_name.set(\"\" + v, k)\n            this._names_list = this._names_list + [k]\n            this._values_list = this._values_list + [v]\n            i = i + 1\n        }\n    }\n\n    func get(name) {\n        if this._name_to_val.has(name) {\n            return this._name_to_val.get(name)\n        }\n        return nullx\n    }\n\n    func name_of(val) {\n        let key = \"\" + val\n        if this._val_to_name.has(key) {\n            return this._val_to_name.get(key)\n        }\n        return nullx\n    }\n\n    func has_name(name) {\n        return this._name_to_val.has(name)\n    }\n\n    func has_val(val) {\n        return this._val_to_name.has(\"\" + val)\n    }\n\n    func names() {\n        return this._names_list\n    }\n\n    func values() {\n        return this._values_list\n    }\n\n    func count() {\n        return len(this._names_list)\n    }\n}\n\nfunc create(items) {\n    return newx Enum(items)\n}\n";

