static const char s_src_error[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# error.mx - error values, result tuples, assertions\n\nclassx MxError {\n    let code = \"\"\n    let message = \"\"\n\n    func init(code, message) {\n        this.code = code\n        this.message = message\n    }\n\n    func to_string() {\n        return \"[\" + this.code + \"] \" + this.message\n    }\n}\n\nfunc make_error(code, message) {\n    return newx MxError(code, message)\n}\n\nfunc throw_error(code, message) {\n    throwx newx MxError(code, message)\n}\n\nfunc panic(message) {\n    throwx newx MxError(\"panic\", message)\n}\n\nfunc is_error(e) {\n    return typeofx(e) == \"MxError\"\n}\n\nfunc error_code(e) {\n    if is_error(e) {\n        return e.code\n    }\n    return \"\"\n}\n\nfunc error_message(e) {\n    if is_error(e) {\n        return e.message\n    }\n    return \"\" + e\n}\n\n# runs fn() -> [\"ok\", value] or [\"err\", thrown]\nfunc attempt(fn) {\n    tryx {\n        return [\"ok\", fn()]\n    } catchx(e) {\n        return [\"err\", e]\n    }\n}\n\nfunc is_ok(r) {\n    return r[0] == \"ok\"\n}\n\nfunc result_value(r) {\n    return r[1]\n}\n\nfunc result_error(r) {\n    return r[1]\n}\n\n\n\n# calls fn up to `times` times; stops at the first [\"ok\", ...]\nfunc retry(times, fn) {\n    let r = [\"err\", \"not attempted\"]\n    let i = 0\n    while i < times {\n        r = attempt(fn)\n        if r[0] == \"ok\" {\n            return r\n        }\n        i = i + 1\n    }\n    return r\n}\n";

