static const char s_src_exception[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# exception.mx - standardized exceptions and error handling (core/)\n# Usage:\n#   importx exception\n#   throwx newx exception.ValueError(\"Invalid age\")\n#   let val = exception.try_or(fn, 0)\n\nclassx Exception {\n    let message = \"\"\n    let kind = \"Exception\"\n\n    func init(msg) {\n        this.message = \"\" + msg\n        this.kind = \"Exception\"\n    }\n\n    func to_string() {\n        return this.kind + \": \" + this.message\n    }\n}\n\nclassx ValueError extends Exception {\n    func init(msg) {\n        super(msg)\n        this.kind = \"ValueError\"\n    }\n}\n\nclassx TypeError extends Exception {\n    func init(msg) {\n        super(msg)\n        this.kind = \"TypeError\"\n    }\n}\n\nclassx KeyError extends Exception {\n    func init(msg) {\n        super(msg)\n        this.kind = \"KeyError\"\n    }\n}\n\nclassx IndexError extends Exception {\n    func init(msg) {\n        super(msg)\n        this.kind = \"IndexError\"\n    }\n}\n\nclassx IOError extends Exception {\n    func init(msg) {\n        super(msg)\n        this.kind = \"IOError\"\n    }\n}\n\nclassx RuntimeError extends Exception {\n    func init(msg) {\n        super(msg)\n        this.kind = \"RuntimeError\"\n    }\n}\n\nfunc raise_if(cond, msg) {\n    if cond {\n        throwx newx Exception(msg)\n    }\n}\n\nfunc raise_unless(cond, msg) {\n    if !cond {\n        throwx newx Exception(msg)\n    }\n}\n\nfunc try_or(fn, fallback) {\n    tryx {\n        return fn()\n    } catchx(e) {\n        return fallback\n    }\n}\n\nfunc try_run(fn) {\n    tryx {\n        return [true, fn()]\n    } catchx(e) {\n        return [false, e]\n    }\n}\n\nfunc format_exception(e) {\n    if typeofx(e) == \"instance\" {\n        return e.to_string()\n    }\n    return \"\" + e\n}\n";

