/* ---- Module: graph (/home/theyad75/Desktop/antmountxlang/shared/stdlib/structs/graph.mx) ---- */
static const char s_src_graph[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# graph.mx - graph data structure with BFS, DFS, and shortest path (structs/)\n# Usage:\n#   importx graph\n#   let g = graph.create(false) # undirected\n#   g.add_edge(\"A\", \"B\", 1)\n#   g.add_edge(\"B\", \"C\", 2)\n#   g.bfs(\"A\")                  # [\"A\", \"B\", \"C\"]\n#   g.shortest_path(\"A\", \"C\")   # [\"A\", \"B\", \"C\"]\n\nimportx dict\nimportx queue\nimportx stack\n\nclassx Graph {\n    let directed = false\n    let _adj = nullx      # dict of node -> Dict(neighbor -> weight)\n    let _nodes = []\n\n    func init(is_directed) {\n        this.directed = is_directed == true\n        this._adj = newx dict.Dict()\n        this._nodes = []\n    }\n\n    func add_node(u) {\n        let key = \"\" + u\n        if !this._adj.has(key) {\n            this._adj.set(key, newx dict.Dict())\n            this._nodes = this._nodes + [u]\n        }\n        return this\n    }\n\n    func add_edge(u, v, weight) {\n        let w = weight\n        if w == nullx { w = 1 }\n        this.add_node(u)\n        this.add_node(v)\n\n        let u_key = \"\" + u\n        let v_key = \"\" + v\n\n        let u_edges = this._adj.get(u_key)\n        u_edges.set(v_key, w)\n\n        if !this.directed {\n            let v_edges = this._adj.get(v_key)\n            v_edges.set(u_key, w)\n        }\n        return this\n    }\n\n    func has_node(u) {\n        return this._adj.has(\"\" + u)\n    }\n\n    func has_edge(u, v) {\n        let u_key = \"\" + u\n        if !this._adj.has(u_key) {\n            return false\n        }\n        let u_edges = this._adj.get(u_key)\n        return u_edges.has(\"\" + v)\n    }\n\n    func edge_weight(u, v) {\n        let u_key = \"\" + u\n        if this._adj.has(u_key) {\n            let u_edges = this._adj.get(u_key)\n            if u_edges.has(\"\" + v) {\n                return u_edges.get(\"\" + v)\n            }\n        }\n        return nullx\n    }\n\n    func neighbors(u) {\n        let u_key = \"\" + u\n        if !this._adj.has(u_key) {\n            return []\n        }\n        let u_edges = this._adj.get(u_key)\n        return u_edges.keys\n    }\n\n    func nodes() {\n        return this._nodes\n    }\n\n    func bfs(start) {\n        let start_key = \"\" + start\n        if !this._adj.has(start_key) {\n            return []\n        }\n        let visited = newx dict.Dict()\n        let q = newx queue.Queue()\n        let order = []\n\n        q.enqueue(start_key)\n        visited.set(start_key, true)\n\n        while !q.is_empty() {\n            let curr = q.dequeue()\n            order = order + [curr]\n\n            let nbrs = this.neighbors(curr)\n            for nbr in nbrs {\n                if !visited.has(nbr) {\n                    visited.set(nbr, true)\n                    q.enqueue(nbr)\n                }\n            }\n        }\n        return order\n    }\n\n    func dfs(start) {\n        let start_key = \"\" + start\n        if !this._adj.has(start_key) {\n            return []\n        }\n        let visited = newx dict.Dict()\n        let st = newx stack.Stack()\n        let order = []\n\n        st.push(start_key)\n\n        while !st.is_empty() {\n            let curr = st.pop()\n            if !visited.has(curr) {\n                visited.set(curr, true)\n                order = order + [curr]\n\n                let nbrs = this.neighbors(curr)\n                # push in reverse order so first neighbor is visited first\n                let i = len(nbrs) - 1\n                while i >= 0 {\n                    let nbr = nbrs[i]\n                    if !visited.has(nbr) {\n                        st.push(nbr)\n                    }\n                    i = i - 1\n                }\n            }\n        }\n        return order\n    }\n\n    func shortest_path(start, target) {\n        let start_key = \"\" + start\n        let target_key = \"\" + target\n        if !this._adj.has(start_key) || !this._adj.has(target_key) {\n            return []\n        }\n        if start_key == target_key {\n            return [start_key]\n        }\n\n        # BFS shortest path tracking predecessors\n        let visited = newx dict.Dict()\n        let parent = newx dict.Dict()\n        let q = newx queue.Queue()\n\n        q.enqueue(start_key)\n        visited.set(start_key, true)\n        let found = false\n\n        while !q.is_empty() && !found {\n            let curr = q.dequeue()\n            let nbrs = this.neighbors(curr)\n            for nbr in nbrs {\n                if !visited.has(nbr) {\n                    visited.set(nbr, true)\n                    parent.set(nbr, curr)\n                    if nbr == target_key {\n                        found = true\n                        break\n                    }\n                    q.enqueue(nbr)\n                }\n            }\n        }\n\n        if !found {\n            return []\n        }\n\n        let path = []\n        let curr = target_key\n        while curr != nullx {\n            path = [curr] + path\n            if curr == start_key {\n                break\n            }\n            if parent.has(curr) {\n                curr = parent.get(curr)\n            } else {\n                curr = nullx\n            }\n        }\n        return path\n    }\n}\n\nfunc create(is_directed) {\n    return newx Graph(is_directed)\n}\n";

