static const char s_src_hashtable[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# hashtable.mx - hash map with separate chaining and automatic rehashing\n# Keys: any value (stringified for hashing, compared with ==)\n\nclassx HashTable {\n    let buckets = []\n    let count = 0\n\n    func init() {\n        let i = 0\n        while i < 16 {\n            this.buckets = this.buckets + [nullx]\n            i = i + 1\n        }\n    }\n\n    # code 0..94 for printable ASCII, 95 for anything else\n    func _char_code(ch) {\n        let table = \" !\\\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]^_`abcdefghijklmnopqrstuvwxyz{|}~\"\n        let idx = this._index(table, ch)\n        if idx < 0 {\n            return 95\n        }\n        return idx\n    }\n\n    # local index_of so this file needs no imports\n    func _index(s, target) {\n        let n = len(s)\n        let m = len(target)\n        if m == 0 {\n            return 0\n        }\n        let i = 0\n        while i <= n - m {\n            let j = 0\n            let ok = true\n            while j < m {\n                if s[i + j] != target[j] {\n                    ok = false\n                    break\n                }\n                j = j + 1\n            }\n            if ok {\n                return i\n            }\n            i = i + 1\n        }\n        return -1\n    }\n\n    func _hash(key) {\n        let s = \"\" + key\n        let h = 7\n        let i = 0\n        while i < len(s) {\n            h = (h * 31 + this._char_code(s[i])) % 1000000007\n            i = i + 1\n        }\n        if h < 0 {\n            h = 0 - h\n        }\n        return h\n    }\n\n    func _bucket_of(key) {\n        return this._hash(key) % len(this.buckets)\n    }\n\n    func _rehash() {\n        let entries = this.entries()\n        let newb = []\n        let i = 0\n        while i < len(this.buckets) * 2 {\n            newb = newb + [nullx]\n            i = i + 1\n        }\n        this.buckets = newb\n        for p in entries {\n            let bi = this._hash(p[0]) % len(this.buckets)\n            let b = this.buckets[bi]\n            if b == nullx {\n                b = []\n            }\n            b = b + [p]\n            this.buckets[bi] = b\n        }\n    }\n\n    func put(key, val) {\n        if (this.count + 1) * 4 > len(this.buckets) * 3 {\n            this._rehash()\n        }\n        let bi = this._bucket_of(key)\n        let b = this.buckets[bi]\n        if b != nullx {\n            for p in b {\n                if p[0] == key {\n                    p[1] = val\n                    return this\n                }\n            }\n        } else {\n            b = []\n        }\n        b = b + [[key, val]]\n        this.buckets[bi] = b\n        this.count = this.count + 1\n        return this\n    }\n\n    func set(key, val) {\n        return this.put(key, val)\n    }\n\n    # nullx when absent (use has() or get_or_default to disambiguate)\n    func get(key) {\n        let b = this.buckets[this._bucket_of(key)]\n        if b == nullx {\n            return nullx\n        }\n        for p in b {\n            if p[0] == key {\n                return p[1]\n            }\n        }\n        return nullx\n    }\n\n    func get_or_default(key, d) {\n        let b = this.buckets[this._bucket_of(key)]\n        if b == nullx {\n            return d\n        }\n        for p in b {\n            if p[0] == key {\n                return p[1]\n            }\n        }\n        return d\n    }\n\n    func has(key) {\n        let b = this.buckets[this._bucket_of(key)]\n        if b == nullx {\n            return false\n        }\n        for p in b {\n            if p[0] == key {\n                return true\n            }\n        }\n        return false\n    }\n\n    # true if the key existed\n    func remove(key) {\n        let bi = this._bucket_of(key)\n        let b = this.buckets[bi]\n        if b == nullx {\n            return false\n        }\n        let nb = []\n        let found = false\n        for p in b {\n            if p[0] == key {\n                found = true\n            } else {\n                nb = nb + [p]\n            }\n        }\n        if found {\n            this.buckets[bi] = nb\n            this.count = this.count - 1\n        }\n        return found\n    }\n\n    func size() {\n        return this.count\n    }\n\n    func is_empty() {\n        return this.count == 0\n    }\n\n    func clear() {\n        this.buckets = []\n        this.count = 0\n        let i = 0\n        while i < 16 {\n            this.buckets = this.buckets + [nullx]\n            i = i + 1\n        }\n    }\n\n    func put_all(pairs) {\n        for p in pairs {\n            this.put(p[0], p[1])\n        }\n        return this\n    }\n\n    func keys() {\n        let out = []\n        for b in this.buckets {\n            if b != nullx {\n                for p in b {\n                    out = out + [p[0]]\n                }\n            }\n        }\n        return out\n    }\n\n    func values() {\n        let out = []\n        for b in this.buckets {\n            if b != nullx {\n                for p in b {\n                    out = out + [p[1]]\n                }\n            }\n        }\n        return out\n    }\n\n    # [[key, value], ...] in no particular order\n    func entries() {\n        let out = []\n        for b in this.buckets {\n            if b != nullx {\n                for p in b {\n                    out = out + [p]\n                }\n            }\n        }\n        return out\n    }\n}\n";

