static const char s_src_http_server[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# http_server.mx - Minimalist, high-performance HTTP/1.1 Web Framework for MountX\n# Provides Request parsing, Response building, Route matching, Middleware, and Server loop.\n\nimportx socket\nimportx string\nimportx json\nimportx net\n\n# ---------------------------------------------------------------------------\n#  Request: Represents incoming HTTP request\n# ---------------------------------------------------------------------------\nclassx Request {\n    func init(method, raw_url, path, query_pairs, headers_pairs, body) {\n        this.method = method\n        this.url = raw_url\n        this.path = path\n        this.query = query_pairs\n        this.headers = headers_pairs\n        this.body = body\n        this.params = []\n    }\n\n    func header(key) {\n        let k_lower = string.lower(key)\n        for h in this.headers {\n            if string.lower(h[0]) == k_lower {\n                return h[1]\n            }\n        }\n        return nullx\n    }\n\n    func query_param(key) {\n        for q in this.query {\n            if q[0] == key {\n                return q[1]\n            }\n        }\n        return nullx\n    }\n\n    func param(key) {\n        for p in this.params {\n            if p[0] == key {\n                return p[1]\n            }\n        }\n        return nullx\n    }\n\n    func json() {\n        if this.body == nullx || this.body == \"\" {\n            return nullx\n        }\n        return json.parse(this.body)\n    }\n}\n\n# ---------------------------------------------------------------------------\n#  JSON Serialization Helper\n# ---------------------------------------------------------------------------\nfunc serialize_http_json(val) {\n    if val == nullx {\n        return \"null\"\n    }\n    let t = typeofx(val)\n    if t == \"Record\" {\n        return val.to_json()\n    }\n    if t == \"array\" {\n        if len(val) == 0 {\n            return \"[]\"\n        }\n        if typeofx(val[0]) == \"array\" && len(val[0]) == 2 && typeofx(val[0][0]) == \"string\" {\n            return json.stringify_pairs(val)\n        }\n        let parts = []\n        let i = 0\n        while i < len(val) {\n            let item = val[i]\n            if typeofx(item) == \"array\" && len(item) > 0 && typeofx(item[0]) == \"array\" && len(item[0]) == 2 && typeofx(item[0][0]) == \"string\" {\n                parts = parts + [json.stringify_pairs(item)]\n            } else {\n                parts = parts + [serialize_http_json(item)]\n            }\n            i = i + 1\n        }\n        return \"[\" + string.join(parts, \",\") + \"]\"\n    }\n    return json.stringify(val)\n}\n\n# ---------------------------------------------------------------------------\n#  Response: Builder for HTTP/1.1 response\n# ---------------------------------------------------------------------------\nclassx Response {\n    func init() {\n        this.status_code = 200\n        this.status_text = \"OK\"\n        this.headers = [\n            [\"Server\", \"MountX-HttpServer/1.0\"],\n            [\"Content-Type\", \"text/plain; charset=utf-8\"],\n            [\"Connection\", \"close\"]\n        ]\n        this.body = \"\"\n        this.is_sent = false\n    }\n\n    func status(code) {\n        this.status_code = code\n        if code == 200 { this.status_text = \"OK\" }\n        else if code == 201 { this.status_text = \"Created\" }\n        else if code == 204 { this.status_text = \"No Content\" }\n        else if code == 400 { this.status_text = \"Bad Request\" }\n        else if code == 401 { this.status_text = \"Unauthorized\" }\n        else if code == 403 { this.status_text = \"Forbidden\" }\n        else if code == 404 { this.status_text = \"Not Found\" }\n        else if code == 405 { this.status_text = \"Method Not Allowed\" }\n        else if code == 500 { this.status_text = \"Internal Server Error\" }\n        else { this.status_text = \"Status \" + code }\n        return this\n    }\n\n    func set_header(key, val) {\n        let found = false\n        let new_headers = []\n        for h in this.headers {\n            if string.lower(h[0]) == string.lower(key) {\n                new_headers = new_headers + [[key, val]]\n                found = true\n            } else {\n                new_headers = new_headers + [h]\n            }\n        }\n        if !found {\n            new_headers = new_headers + [[key, val]]\n        }\n        this.headers = new_headers\n        return this\n    }\n\n    func send(text) {\n        this.body = \"\" + text\n        this.set_header(\"Content-Length\", \"\" + len(this.body))\n        this.is_sent = true\n        return this\n    }\n\n    func text(plain_text) {\n        this.set_header(\"Content-Type\", \"text/plain; charset=utf-8\")\n        return this.send(plain_text)\n    }\n\n    func html(html_content) {\n        this.set_header(\"Content-Type\", \"text/html; charset=utf-8\")\n        return this.send(html_content)\n    }\n\n    func json(data) {\n        this.set_header(\"Content-Type\", \"application/json; charset=utf-8\")\n        let json_str = serialize_http_json(data)\n        return this.send(json_str)\n    }\n\n    func build() {\n        let lines = [\"HTTP/1.1 \" + this.status_code + \" \" + this.status_text]\n        for h in this.headers {\n            lines = lines + [h[0] + \": \" + h[1]]\n        }\n        return string.join(lines, \"\\r\\n\") + \"\\r\\n\\r\\n\" + this.body\n    }\n}\n\n# ---------------------------------------------------------------------------\n#  Parsing & Matching Helpers\n# ---------------------------------------------------------------------------\nfunc parse_request(raw_text) {\n    let sep = string.index_of(raw_text, \"\\r\\n\\r\\n\")\n    let head_str = raw_text\n    let body_str = \"\"\n    if sep >= 0 {\n        head_str = string.substr(raw_text, 0, sep)\n        body_str = string.substr(raw_text, sep + 4, len(raw_text))\n    }\n    let lines = string.split(head_str, \"\\r\\n\")\n    if len(lines) == 1 {\n        lines = string.split(head_str, \"\\n\")\n    }\n    if len(lines) == 0 {\n        return newx Request(\"GET\", \"/\", \"/\", [], [], \"\")\n    }\n\n    let req_line = lines[0]\n    let parts = string.split(req_line, \" \")\n    let method = \"GET\"\n    let raw_url = \"/\"\n    if len(parts) > 0 { method = parts[0] }\n    if len(parts) > 1 { raw_url = parts[1] }\n\n    let path = raw_url\n    let query_pairs = []\n    let q_idx = string.index_of(raw_url, \"?\")\n    if q_idx >= 0 {\n        path = string.substr(raw_url, 0, q_idx)\n        let q_str = string.substr(raw_url, q_idx + 1, len(raw_url))\n        query_pairs = net.query_parse(q_str)\n    }\n\n    let headers = []\n    let i = 1\n    while i < len(lines) {\n        let line = lines[i]\n        let c_idx = string.index_of(line, \":\")\n        if c_idx > 0 {\n            let k = string.trim(string.substr(line, 0, c_idx))\n            let v = string.trim(string.substr(line, c_idx + 1, len(line)))\n            headers = headers + [[k, v]]\n        }\n        i = i + 1\n    }\n\n    return newx Request(method, raw_url, path, query_pairs, headers, body_str)\n}\n\nfunc match_route(pattern, path) {\n    if pattern == path {\n        return [true, []]\n    }\n    let pat_parts = string.split(pattern, \"/\")\n    let path_parts = string.split(path, \"/\")\n    if len(pat_parts) != len(path_parts) {\n        return [false, []]\n    }\n    let params = []\n    let i = 0\n    while i < len(pat_parts) {\n        let p_item = pat_parts[i]\n        let r_item = path_parts[i]\n        if string.starts_with(p_item, \":\") {\n            let p_name = string.substr(p_item, 1, len(p_item))\n            params = params + [[p_name, r_item]]\n        } else if p_item != r_item {\n            return [false, []]\n        }\n        i = i + 1\n    }\n    return [true, params]\n}\n\n# ---------------------------------------------------------------------------\n#  App: Core Web Application Framework\n# ---------------------------------------------------------------------------\nclassx App {\n    func init() {\n        this.routes = []\n        this.middlewares = []\n        this.server_fd = nullx\n        this.running = false\n    }\n\n    func use(middleware_func) {\n        this.middlewares = this.middlewares + [middleware_func]\n        return this\n    }\n\n    func add_route(method, pattern, handler) {\n        this.routes = this.routes + [[string.upper(method), pattern, handler]]\n        return this\n    }\n\n    func get(pattern, handler) {\n        return this.add_route(\"GET\", pattern, handler)\n    }\n\n    func post(pattern, handler) {\n        return this.add_route(\"POST\", pattern, handler)\n    }\n\n    func put(pattern, handler) {\n        return this.add_route(\"PUT\", pattern, handler)\n    }\n\n    func delete(pattern, handler) {\n        return this.add_route(\"DELETE\", pattern, handler)\n    }\n\n    func handle_raw(raw_text) {\n        let req = parse_request(raw_text)\n        let res = newx Response()\n\n        # Execute middlewares\n        for m in this.middlewares {\n            m(req, res)\n            if res.is_sent {\n                return res.build()\n            }\n        }\n\n        # Match routes\n        let matched = false\n        for r in this.routes {\n            if !matched {\n                let r_method = r[0]\n                let r_pattern = r[1]\n                let r_handler = r[2]\n\n                if r_method == req.method {\n                    let match_res = match_route(r_pattern, req.path)\n                    if match_res[0] {\n                        req.params = match_res[1]\n                        matched = true\n                        r_handler(req, res)\n                    }\n                }\n            }\n        }\n\n        if !matched {\n            res.status(404)\n            res.json([\n                [\"error\", \"Not Found\"],\n                [\"method\", req.method],\n                [\"path\", req.path]\n            ])\n        }\n\n        return res.build()\n    }\n\n    func listen(port, host, max_requests) {\n        let bind_host = host\n        if bind_host == nullx {\n            bind_host = \"0.0.0.0\"\n        }\n        this.server_fd = socket.listen(port, bind_host)\n        this.running = true\n        printx(\"==================================================\")\n        printx(\"  \360\237\232\200 MountX Web Application Running!\")\n        printx(\"  \360\237\214\220 Listening on: http://\" + bind_host + \":\" + port)\n        printx(\"==================================================\")\n\n        let req_count = 0\n        while this.running {\n            let conn = socket.accept(this.server_fd)\n            if conn != nullx && typeofx(conn) == \"array\" && len(conn) >= 2 {\n                let client_fd = conn[0]\n                let client_ip = conn[1]\n\n                if client_fd > 0 {\n                    let raw_data = socket.recv(client_fd, 8192)\n                    if raw_data != nullx && raw_data != \"\" {\n                        let resp_text = this.handle_raw(raw_data)\n                        socket.send(client_fd, resp_text)\n                    }\n                    socket.close(client_fd)\n                    req_count = req_count + 1\n                    if max_requests != nullx && req_count >= max_requests {\n                        this.running = false\n                    }\n                }\n            }\n        }\n        socket.close(this.server_fd)\n        this.server_fd = nullx\n    }\n}\n\nfunc new_app() {\n    return newx App()\n}\n";

