static const char s_src_io[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# io.mx - safe wrappers over readx/writex/appendx\n# read_text returns nullx when the file cannot be read (missing, no permission).\n\nimportx string\n\nfunc read_text(path) {\n    tryx {\n        return readx(path)\n    } catchx(e) {\n        return nullx\n    }\n}\n\nfunc write_text(path, content) {\n    tryx {\n        writex(path, content)\n        return true\n    } catchx(e) {\n        return false\n    }\n}\n\nfunc append_text(path, content) {\n    tryx {\n        appendx(path, content)\n        return true\n    } catchx(e) {\n        return false\n    }\n}\n\n# nullx if unreadable; a file ending in \"\\n\" yields a trailing \"\" element\nfunc read_lines(path) {\n    let text = read_text(path)\n    if text == nullx {\n        return nullx\n    }\n    let lines = string.split(text, \"\\n\")\n    let i = 0\n    while i < len(lines) {\n        let ln = lines[i]\n        if len(ln) > 0 {\n            if ln[len(ln) - 1] == \"\\r\" {\n                lines[i] = string.substr(ln, 0, len(ln) - 1)\n            }\n        }\n        i = i + 1\n    }\n    return lines\n}\n\nfunc write_lines(path, lines) {\n    return write_text(path, string.join(lines, \"\\n\"))\n}\n\nfunc append_line(path, line) {\n    let existing = read_text(path)\n    if existing == nullx {\n        return append_text(path, line + \"\\n\")\n    }\n    if len(existing) == 0 {\n        return append_text(path, line + \"\\n\")\n    }\n    if existing[len(existing) - 1]!= \"\\n\" {\n        return append_text(path, \"\\n\" + line + \"\\n\")\n    }\n    return append_text(path, line + \"\\n\")\n}\n\nfunc file_exists(path) {\n    return read_text(path)!= nullx\n}";

