static const char s_src_iter[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# iter.mx - building and segmenting sequences (all eager/finite)\n\nfunc range(n) {\n    let out = []\n    let i = 0\n    while i < n {\n        out = out + [i]\n        i = i + 1\n    }\n    return out\n}\n\nfunc range_from(lo, hi) {\n    let out = []\n    let i = lo\n    while i < hi {\n        out = out + [i]\n        i = i + 1\n    }\n    return out\n}\n\n# step may be negative\nfunc range_step(lo, hi, step) {\n    if step == 0 {\n        throwx \"range_step: step cannot be 0\"\n    }\n    let out = []\n    let i = lo\n    if step > 0 {\n        while i < hi {\n            out = out + [i]\n            i = i + step\n        }\n    } else {\n        while i > hi {\n            out = out + [i]\n            i = i + step\n        }\n    }\n    return out\n}\n\n# -> [[0, a[0]], [1, a[1]], ...]\nfunc enumerate(a) {\n    let out = []\n    let i = 0\n    while i < len(a) {\n        out = out + [[i, a[i]]]\n        i = i + 1\n    }\n    return out\n}\n\nfunc zip(a, b) {\n    let n = len(a)\n    if len(b) < n {\n        n = len(b)\n    }\n    let out = []\n    let i = 0\n    while i < n {\n        out = out + [[a[i], b[i]]]\n        i = i + 1\n    }\n    return out\n}\n\n# sliding windows of length n\nfunc windows(arr, n) {\n    if n <= 0 {\n        throwx \"windows: n must be >= 1\"\n    }\n    let out = []\n    let i = 0\n    while i + n <= len(arr) {\n        let w = []\n        let j = i\n        while j < i + n {\n            w = w + [arr[j]]\n            j = j + 1\n        }\n        out = out + [w]\n        i = i + 1\n    }\n    return out\n}\n\n# consecutive chunks of size n (last may be shorter)\nfunc chunks(arr, n) {\n    if n <= 0 {\n        throwx \"chunks: n must be >= 1\"\n    }\n    let out = []\n    let i = 0\n    while i < len(arr) {\n        let c = []\n        let j = i\n        while j < i + n {\n            if j < len(arr) {\n                c = c + [arr[j]]\n            }\n            j = j + 1\n        }\n        out = out + [c]\n        i = i + n\n    }\n    return out\n}\n\n# running results of fn(acc, x), starting from init\nfunc scan(arr, fn, init) {\n    let acc = init\n    let out = []\n    for x in arr {\n        acc = fn(acc, x)\n        out = out + [acc]\n    }\n    return out\n}\n\n# stops at the FIRST element where fn is false\nfunc take_while(arr, fn) {\n    let out = []\n    for x in arr {\n        if !fn(x) {\n            return out\n        }\n        out = out + [x]\n    }\n    return out\n}\n\nfunc drop_while(arr, fn) {\n    let i = 0\n    while i < len(arr) {\n        if !fn(arr[i]) {\n            break\n        }\n        i = i + 1\n    }\n    let out = []\n    while i < len(arr) {\n        out = out + [arr[i]]\n        i = i + 1\n    }\n    return out\n}\n\n# fn(x) must return an array; results are concatenated in order\nfunc flat_map(arr, fn) {\n    let out = []\n    for x in arr {\n        out = out + fn(x)\n    }\n    return out\n}\n\n# calls fn(i) for i in 0..n-1 and collects the results\nfunc iterate(n, fn) {\n    let out = []\n    let i = 0\n    while i < n {\n        out = out + [fn(i)]\n        i = i + 1\n    }\n    return out\n}\n";

