static const char s_src_linkedlist[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# linkedlist.mx - singly linked list with O(1) front/back ops\n\nclassx LLNode {\n    let val = nullx\n    let next = nullx\n\n    func init(v) {\n        this.val = v\n    }\n}\n\nclassx LinkedList {\n    let head = nullx\n    let tail = nullx\n    let count = 0\n\n    func add_front(v) {\n        let node = newx LLNode(v)\n        node.next = this.head\n        this.head = node\n        if this.tail == nullx {\n            this.tail = node\n        }\n        this.count = this.count + 1\n        return this\n    }\n\n    func add_back(v) {\n        let node = newx LLNode(v)\n        if this.tail == nullx {\n            this.head = node\n            this.tail = node\n        } else {\n            this.tail.next = node\n            this.tail = node\n        }\n        this.count = this.count + 1\n        return this\n    }\n\n    # nullx when empty\n    func remove_front() {\n        if this.head == nullx {\n            return nullx\n        }\n        let v = this.head.val\n        this.head = this.head.next\n        if this.head == nullx {\n            this.tail = nullx\n        }\n        this.count = this.count - 1\n        return v\n    }\n\n    func peek_front() {\n        if this.head == nullx {\n            return nullx\n        }\n        return this.head.val\n    }\n\n    func peek_back() {\n        if this.tail == nullx {\n            return nullx\n        }\n        return this.tail.val\n    }\n\n    func size() {\n        return this.count\n    }\n\n    func is_empty() {\n        return this.count == 0\n    }\n\n    func contains(v) {\n        let cur = this.head\n        while cur != nullx {\n            if cur.val == v {\n                return true\n            }\n            cur = cur.next\n        }\n        return false\n    }\n\n    # removes the first node whose val == v; true if removed\n    func remove_first(v) {\n        let prev = nullx\n        let cur = this.head\n        while cur != nullx {\n            if cur.val == v {\n                if prev == nullx {\n                    this.head = cur.next\n                } else {\n                    prev.next = cur.next\n                }\n                if this.tail == cur {\n                    this.tail = prev\n                }\n                this.count = this.count - 1\n                return true\n            }\n            prev = cur\n            cur = cur.next\n        }\n        return false\n    }\n\n    # reverses in place\n    func reverse() {\n        let old_head = this.head\n        let prev = nullx\n        let cur = this.head\n        while cur != nullx {\n            let nxt = cur.next\n            cur.next = prev\n            prev = cur\n            cur = nxt\n        }\n        this.head = prev\n        this.tail = old_head\n        return this\n    }\n\n    func clear() {\n        this.head = nullx\n        this.tail = nullx\n        this.count = 0\n    }\n\n    # front -> back\n    func to_array() {\n        let out = []\n        let cur = this.head\n        while cur != nullx {\n            out = out + [cur.val]\n            cur = cur.next\n        }\n        return out\n    }\n}\n";

