static const char s_src_map[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# map.mx - Map class (dict.Dict-compatible: has .keys/.values fields)\n# plus helpers for \"pairs\" values: [[key, value], ...] (what json.parse returns)\n\nfunc pairs_has(pairs, k) {\n    for p in pairs {\n        if p[0] == k {\n            return true\n        }\n    }\n    return false\n}\n\n# value or nullx\nfunc pairs_get(pairs, k) {\n    for p in pairs {\n        if p[0] == k {\n            return p[1]\n        }\n    }\n    return nullx\n}\n\n# updates the existing pair IN PLACE; otherwise returns a new list.\n# ALWAYS use the return value:  let ps = pairs_set(ps, \"a\", 1)\nfunc pairs_set(pairs, k, v) {\n    for p in pairs {\n        if p[0] == k {\n            p[1] = v\n            return pairs\n        }\n    }\n    return pairs + [[k, v]]\n}\n\nfunc pairs_remove(pairs, k) {\n    let out = []\n    for p in pairs {\n        if p[0] != k {\n            out = out + [p]\n        }\n    }\n    return out\n}\n\nfunc pairs_keys(pairs) {\n    let out = []\n    for p in pairs {\n        out = out + [p[0]]\n    }\n    return out\n}\n\nfunc pairs_values(pairs) {\n    let out = []\n    for p in pairs {\n        out = out + [p[1]]\n    }\n    return out\n}\n\n# entries from b override entries from a\nfunc pairs_merge(a, b) {\n    let out = a\n    for p in b {\n        out = pairs_set(out, p[0], p[1])\n    }\n    return out\n}\n\nclassx Map {\n    let keys = []\n    let values = []\n\n    func _find(k) {\n        let i = 0\n        while i < len(this.keys) {\n            if this.keys[i] == k {\n                return i\n            }\n            i = i + 1\n        }\n        return -1\n    }\n\n    func set(k, v) {\n        let i = this._find(k)\n        if i >= 0 {\n            this.values[i] = v\n        } else {\n            this.keys = this.keys + [k]\n            this.values = this.values + [v]\n        }\n        return this\n    }\n\n    func get(k) {\n        let i = this._find(k)\n        if i >= 0 {\n            return this.values[i]\n        }\n        return nullx\n    }\n\n    func get_or_default(k, d) {\n        let i = this._find(k)\n        if i >= 0 {\n            return this.values[i]\n        }\n        return d\n    }\n\n    func has(k) {\n        return this._find(k) != -1\n    }\n\n    func remove(k) {\n        let i = this._find(k)\n        if i < 0 {\n            return false\n        }\n        let nk = []\n        let nv = []\n        let j = 0\n        while j < len(this.keys) {\n            if j != i {\n                nk = nk + [this.keys[j]]\n                nv = nv + [this.values[j]]\n            }\n            j = j + 1\n        }\n        this.keys = nk\n        this.values = nv\n        return true\n    }\n\n    func size() {\n        return len(this.keys)\n    }\n\n    func clear() {\n        this.keys = []\n        this.values = []\n    }\n\n    # returns the final value for k\n    func set_if_absent(k, v) {\n        let i = this._find(k)\n        if i >= 0 {\n            return this.values[i]\n        }\n        this.keys = this.keys + [k]\n        this.values = this.values + [v]\n        return v\n    }\n\n    # fn(old_value) -> new value; old is nullx when k is absent\n    func update(k, fn) {\n        let nv = fn(this.get_or_default(k, nullx))\n        this.set(k, nv)\n        return nv\n    }\n\n    func merge_pairs(pairs) {\n        for p in pairs {\n            this.set(p[0], p[1])\n        }\n        return this\n    }\n\n    # fn(old_value) -> new value, applied to every value\n    func map_values(fn) {\n        let i = 0\n        while i < len(this.values) {\n            this.values[i] = fn(this.values[i])\n            i = i + 1\n        }\n        return this\n    }\n\n    # fn(k, v) -> bool keeps the entry\n    func filter_entries(fn) {\n        let nk = []\n        let nv = []\n        let i = 0\n        while i < len(this.keys) {\n            if fn(this.keys[i], this.values[i]) {\n                nk = nk + [this.keys[i]]\n                nv = nv + [this.values[i]]\n            }\n            i = i + 1\n        }\n        this.keys = nk\n        this.values = nv\n        return this\n    }\n\n    func get_keys() {\n        return this.keys + []\n    }\n\n    func get_values() {\n        return this.values + []\n    }\n\n    # [[k, v], ...] - same shape json.parse produces\n    func entries() {\n        let out = []\n        let i = 0\n        while i < len(this.keys) {\n            out = out + [[this.keys[i], this.values[i]]]\n            i = i + 1\n        }\n        return out\n    }\n\n    func clone() {\n        let m = newx Map()\n        m.keys = this.keys + []\n        m.values = this.values + []\n        return m\n    }\n}\n";

