/* ---- Module: math (/home/theyad75/Desktop/antmountxlang/shared/stdlib/math/math.mx) ---- */
static const char s_src_math[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# math.mx - MountX Standard Library\n\nfunc abs(x) {\n    if x < 0 {\n        return 0 - x\n    }\n    return x\n}\n\nfunc max(a, b) {\n    if a > b {\n        return a\n    }\n    return b\n}\n\nfunc min(a, b) {\n    if a > b {\n        return b\n    }\n    return a\n}\n\nfunc pow(base, exp) {\n    # FIX: negative exponent silently returned 1 before (loop ran 0 times)\n    if exp < 0 {\n        throwx \"pow: negative exponents are not supported\"\n    }\n    let result = 1\n    loop exp {\n        result = result * base\n    }\n    return result\n}\n\nfunc factorial(n) {\n    if n <= 1 {\n        return 1\n    }\n    return n * factorial(n - 1)\n}\n\nfunc clamp(x, lo, hi) {\n    if x < lo {\n        return lo\n    }\n    if x > hi {\n        return hi\n    }\n    return x\n}";

