/* ---- Module: mathfull (/home/theyad75/Desktop/antmountxlang/shared/stdlib/math/mathfull.mx) ---- */
static const char s_src_mathfull[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# mathfull.mx - extra math (fast natives: math_floor + idiv)\n\nimportx string\n\n# integer division, truncates toward zero; b must not be 0\n# Now a thin wrapper over native idiv (exact for big ints)\nfunc idiv(a, b) {\n    return idiv(a, b)\n}\n\nfunc floor(x) {\n    let t = typeofx(x)\n    if t == \"int\" { return x }\n    if t != \"float\" { throwx \"floor expects a number\" }\n    return math_floor(x)\n}\n\nfunc trunc(x) {\n    let t = typeofx(x)\n    if t == \"int\" { return x }\n    if t != \"float\" { throwx \"trunc expects a number\" }\n    if x >= 0 {\n        return math_floor(x)\n    }\n    return 0 - math_floor(0 - x)\n}\n\nfunc ceil(x) {\n    let t = typeofx(x)\n    if t == \"int\" { return x }\n    if t != \"float\" { throwx \"ceil expects a number\" }\n    return 0 - math_floor(0 - x)\n}\n\n# rounds half away from zero\nfunc round(x) {\n    if x >= 0 {\n        return trunc(x + 0.5)\n    }\n    return trunc(x - 0.5)\n}\n\nfunc sign(x) {\n    if x > 0 {\n        return 1\n    }\n    if x < 0 {\n        return -1\n    }\n    return 0\n}\n\nfunc is_even(n) {\n    return n % 2 == 0\n}\n\nfunc is_odd(n) {\n    return n % 2 != 0\n}\n\n# integer exponent >= 0 (stays exact for ints)\nfunc ipow(base, exp) {\n    if exp < 0 {\n        throwx \"ipow: exponent must be >= 0\"\n    }\n    let result = 1\n    while exp > 0 {\n        if exp % 2 == 1 {\n            result = result * base\n        }\n        base = base * base\n        exp = idiv(exp, 2)\n    }\n    return result\n}\n\nfunc gcd(a, b) {\n    if a < 0 {\n        a = 0 - a\n    }\n    if b < 0 {\n        b = 0 - b\n    }\n    while b != 0 {\n        let t = a % b\n        a = b\n        b = t\n    }\n    return a\n}\n\nfunc lcm(a, b) {\n    if a == 0 || b == 0 {\n        return 0\n    }\n    return idiv(a, gcd(a, b)) * b\n}\n\nfunc is_prime(n) {\n    if n < 2 {\n        return false\n    }\n    if n < 4 {\n        return true\n    }\n    if n % 2 == 0 {\n        return false\n    }\n    let i = 3\n    while i * i <= n {\n        if n % i == 0 {\n            return false\n        }\n        i = i + 2\n    }\n    return true\n}\n\n# trial division; fine for n up to a few thousand\nfunc primes_below(n) {\n    let out = []\n    let i = 2\n    while i < n {\n        if is_prime(i) {\n            out = out + [i]\n        }\n        i = i + 1\n    }\n    return out\n}\n\n# Newton's method; returns a float\nfunc sqrt(n) {\n    if n < 0 {\n        throwx \"sqrt of negative number\"\n    }\n    if n == 0 {\n        return 0\n    }\n    let x = 1\n    while x * x <= n {\n        x = x * 2\n    }\n    loop 60 {\n        x = (x + n / x) / 2\n    }\n    return x\n}\n\n# digits of |n|, most significant first: digits(3407) -> [3, 4, 0, 7]\nfunc digits(n) {\n    if typeofx(n) != \"int\" {\n        throwx \"digits expects an int\"\n    }\n    if n < 0 {\n        n = 0 - n\n    }\n    let s = \"\" + n\n    let dg = \"0123456789\"\n    let out = []\n    let i = 0\n    while i < len(s) {\n        let d = string.index_of(dg, s[i])\n        if d < 0 {\n            throwx \"digits: unexpected character\"\n        }\n        out = out + [d]\n        i = i + 1\n    }\n    return out\n}\n\n# inverse of digits: undigits([3, 4, 0, 7]) -> 3407\nfunc undigits(ds) {\n    let v = 0\n    for d in ds {\n        if d < 0 || d > 9 {\n            throwx \"undigits: values must be 0..9\"\n        }\n        v = v * 10 + d\n    }\n    return v\n}\n\nfunc sum_digits(n) {\n    let s = 0\n    for d in digits(n) {\n        s = s + d\n    }\n    return s\n}\n\n# value -> string in base b (2..36); negatives get a leading \"-\"\nfunc to_base(n, b) {\n    if b < 2 || b > 36 {\n        throwx \"to_base: base must be 2..36\"\n    }\n    let ch = \"0123456789abcdefghijklmnopqrstuvwxyz\"\n    if n == 0 {\n        return \"0\"\n    }\n    let neg = false\n    if n < 0 {\n        neg = true\n        n = 0 - n\n    }\n    let ds = []\n    while n > 0 {\n        ds = ds + [n % b]\n        n = idiv(n, b)\n    }\n    let out = \"\"\n    let i = len(ds) - 1\n    while i >= 0 {\n        out = out + ch[ds[i]]\n        i = i - 1\n    }\n    if neg {\n        return \"-\" + out\n    }\n    return out\n}\n\n# string in base b (2..36) -> int; optional leading \"-\"\nfunc from_base(s, b) {\n    if b < 2 || b > 36 {\n        throwx \"from_base: base must be 2..36\"\n    }\n    let ch = \"0123456789abcdefghijklmnopqrstuvwxyz\"\n    let t = string.trim(s)\n    if len(t) == 0 {\n        throwx \"from_base: empty string\"\n    }\n    let i = 0\n    let neg = false\n    if t[0] == \"-\" {\n        neg = true\n        i = 1\n    }\n    if i >= len(t) {\n        throwx \"from_base: no digits\"\n    }\n    let v = 0\n    while i < len(t) {\n        let d = string.index_of(ch, string.lower(t[i]))\n        if d < 0 || d >= b {\n            throwx \"from_base: bad digit '\" + t[i] + \"' for base \" + b\n        }\n        v = v * b + d\n        i = i + 1\n    }\n    if neg {\n        return 0 - v\n    }\n    return v\n}\n";

