static const char s_src_net[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# net.mx - URL / query-string / HTTP-message toolkit.\n# mountx has no sockets, so nothing here opens a connection by itself\n# EXCEPT fetch(), which requires the tiny native `http_get` builtin\n# (the paste-ready Python is in the comment at the bottom).\n\nimportx string\nimportx mathfull\nimportx map\nimportx socket\n\n# table of printable ASCII 32..126: index + 32 = character code\nfunc _char_code(ch) {\n    let table = \" !\\\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]^_`abcdefghijklmnopqrstuvwxyz{|}~\"\n    return string.index_of(table, ch)\n}\n\nfunc _hex_val(ch) {\n    let d = string.index_of(\"0123456789abcdef\", ch)\n    if d >= 0 {\n        return d\n    }\n    return string.index_of(\"0123456789ABCDEF\", ch)\n}\n\nfunc url_encode(s) {\n    let lo = \"abcdefghijklmnopqrstuvwxyz\"\n    let up = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n    let dg = \"0123456789\"\n    let extra = \"-._~\"\n    let hex = \"0123456789ABCDEF\"\n    let out = \"\"\n    let i = 0\n    while i < len(s) {\n        let ch = s[i]\n        if string.index_of(lo, ch) >= 0 || string.index_of(up, ch) >= 0 || string.index_of(dg, ch) >= 0 || string.index_of(extra, ch) >= 0 {\n            out = out + ch\n        } else {\n            let idx = _char_code(ch)\n            if idx < 0 {\n                throwx \"url_encode: character not encodable: \" + ch\n            }\n            let code = idx + 32\n            out = out + \"%\" + hex[mathfull.idiv(code, 16)] + hex[code % 16]\n        }\n        i = i + 1\n    }\n    return out\n}\n\nfunc url_decode(s) {\n    let table = \" !\\\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]^_`abcdefghijklmnopqrstuvwxyz{|}~\"\n    let out = \"\"\n    let i = 0\n    while i < len(s) {\n        let ch = s[i]\n        if ch == \"%\" {\n            if i + 2 >= len(s) {\n                throwx \"url_decode: truncated % escape\"\n            }\n            let h1 = _hex_val(s[i + 1])\n            let h2 = _hex_val(s[i + 2])\n            if h1 < 0 || h2 < 0 {\n                throwx \"url_decode: bad % escape\"\n            }\n            let code = h1 * 16 + h2\n            if code == 10 {\n                out = out + \"\\n\"\n            } else if code == 9 {\n                out = out + \"\\t\"\n            } else if code == 13 {\n                out = out + \"\\r\"\n            } else if code >= 32 && code <= 126 {\n                out = out + table[code - 32]\n            } else {\n                throwx \"url_decode: unsupported character code \" + code\n            }\n            i = i + 3\n        } else if ch == \"+\" {\n            out = out + \" \"\n            i = i + 1\n        } else {\n            out = out + ch\n            i = i + 1\n        }\n    }\n    return out\n}\n\n# -> [[\"scheme\", s], [\"host\", h], [\"port\", p], [\"path\", p], [\"query\", q], [\"fragment\", f]]\n# missing parts are \"\"\nfunc url_parse(u) {\n    let rest = u\n    let scheme = \"\"\n    let sc = string.index_of(rest, \"://\")\n    if sc >= 0 {\n        scheme = string.substr(rest, 0, sc)\n        rest = string.substr(rest, sc + 3, len(rest))\n    }\n    let fragment = \"\"\n    let fi = string.index_of(rest, \"#\")\n    if fi >= 0 {\n        fragment = string.substr(rest, fi + 1, len(rest))\n        rest = string.substr(rest, 0, fi)\n    }\n    let query = \"\"\n    let qi = string.index_of(rest, \"?\")\n    if qi >= 0 {\n        query = string.substr(rest, qi + 1, len(rest))\n        rest = string.substr(rest, 0, qi)\n    }\n    let path = \"/\"\n    let pi = string.index_of(rest, \"/\")\n    if pi >= 0 {\n        path = string.substr(rest, pi, len(rest))\n        rest = string.substr(rest, 0, pi)\n    }\n    let host = rest\n    let port = \"\"\n    let pcol = string.index_of(host, \":\")\n    if pcol >= 0 {\n        port = string.substr(host, pcol + 1, len(host))\n        host = string.substr(host, 0, pcol)\n    }\n    return [[\"scheme\", scheme], [\"host\", host], [\"port\", port], [\"path\", path], [\"query\", query], [\"fragment\", fragment]]\n}\n\n# pass what url_parse returned\nfunc url_build(parts) {\n    let u = map.pairs_get(parts, \"scheme\")\n    if u != \"\" {\n        u = u + \"://\"\n    }\n    u = u + map.pairs_get(parts, \"host\")\n    let port = map.pairs_get(parts, \"port\")\n    if port != \"\" {\n        u = u + \":\" + port\n    }\n    u = u + map.pairs_get(parts, \"path\")\n    let q = map.pairs_get(parts, \"query\")\n    if q != \"\" {\n        u = u + \"?\" + q\n    }\n    let f = map.pairs_get(parts, \"fragment\")\n    if f != \"\" {\n        u = u + \"#\" + f\n    }\n    return u\n}\n\n# [[\"k\", v], ...] -> \"k=v&k2=v2\" (values are stringified)\nfunc query_encode(pairs) {\n    let parts = []\n    for p in pairs {\n        parts = parts + [url_encode(\"\" + p[0]) + \"=\" + url_encode(\"\" + p[1])]\n    }\n    return string.join(parts, \"&\")\n}\n\n# \"a=1&b=two\" -> [[\"a\", \"1\"], [\"b\", \"two\"]] (all values are strings)\nfunc query_parse(qs) {\n    let out = []\n    if qs == \"\" {\n        return out\n    }\n    for part in string.split(qs, \"&\") {\n        let eq = string.index_of(part, \"=\")\n        if eq < 0 {\n            out = out + [[url_decode(part), \"\"]]\n        } else {\n            out = out + [[url_decode(string.substr(part, 0, eq)), url_decode(string.substr(part, eq + 1, len(part)))]]\n        }\n    }\n    return out\n}\n\n# builds a raw HTTP/1.1 request string\nfunc http_request_text(method, url, headers_pairs, body) {\n    let p = url_parse(url)\n    let host = map.pairs_get(p, \"host\")\n    let port = map.pairs_get(p, \"port\")\n    if port != \"\" {\n        host = host + \":\" + port\n    }\n    let lines = [method + \" \" + map.pairs_get(p, \"path\") + \" HTTP/1.1\"]\n    lines = lines + [\"Host: \" + host]\n    for h in headers_pairs {\n        lines = lines + [\"\" + h[0] + \": \" + h[1]]\n    }\n    if body != \"\" {\n        lines = lines + [\"Content-Length: \" + len(body)]\n    }\n    return string.join(lines, \"\\r\\n\") + \"\\r\\n\\r\\n\" + body\n}\n\n# -> [status_int, header_pairs, body]\nfunc http_parse_response(text) {\n    let sep = string.index_of(text, \"\\r\\n\\r\\n\")\n    let head = text\n    let body = \"\"\n    if sep >= 0 {\n        head = string.substr(text, 0, sep)\n        body = string.substr(text, sep + 4, len(text))\n    }\n    let lines = string.split(head, \"\\r\\n\")\n    let status = 0\n    if len(lines) > 0 {\n        let sp = string.split(lines[0], \" \")\n        if len(sp) > 1 {\n            let code = string.tonum(sp[1])\n            if code != nullx {\n                status = code\n            }\n        }\n    }\n    let headers = []\n    let i = 1\n    while i < len(lines) {\n        let ln = lines[i]\n        let c = string.index_of(ln, \":\")\n        if c >= 0 {\n            headers = headers + [[string.trim(string.substr(ln, 0, c)), string.trim(string.substr(ln, c + 1, len(ln)))]]\n        }\n        i = i + 1\n    }\n    return [status, headers, body]\n}\n\n# fetch(url) -> body string. REQUIRES this native builtin pasted into\n# eval_call in interpreter.py (next to the \"len\" builtin):\n#\n#   if name == \"http_get\":\n#       if len(args) != 1 or not isinstance(args[0], str):\n#           raise RuntimeError(\"http_get expects 1 string argument\")\n#       import urllib.request, urllib.error\n#       try:\n#           with urllib.request.urlopen(args[0], timeout=15) as resp:\n#               return resp.read().decode(\"utf-8\", \"replace\")\n#       except (urllib.error.URLError, OSError) as e:\n#           raise RuntimeError(f\"http_get failed: {e}\")\nfunc fetch(url) {\n    return http_get(url)\n}\n\nfunc post(url, body, content_type) {\n    if content_type == nullx {\n        return http_post(url, body)\n    }\n    return http_post(url, body, content_type)\n}\n\nfunc serve_http(port, handler, max_requests) {\n    let s = newx socket.TcpServer(port, nullx)\n    s.start()\n    let count = 0\n    while max_requests == nullx || count < max_requests {\n        let conn = s.accept()\n        let cfd = conn[0]\n        let raw = socket.recv(cfd, 4096)\n        if len(raw) > 0 {\n            let res = handler(raw)\n            socket.send(cfd, res)\n        }\n        socket.close(cfd)\n        count = count + 1\n    }\n    s.close()\n    return count\n}\n";

