static const char s_src_orm[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# orm.mx - Lightweight ORM and Fluent Query Builder for MountX (SQLite)\n#\n# Provides:\n#   - Database: SQLite connection manager with schema inspection\n#   - QueryBuilder: fluent queries (where, orderBy, limit, offset, insert, update, delete, count, pluck)\n#   - Record: row object with named column access (.get, .set, .to_pairs, .to_json)\n#   - Model: base Active Record class for clean OOP entity management\n#   - Global helpers: connect(path), table(name), default_db()\n\nimportx string\nimportx json\n\n# ---------------------------------------------------------------------------\n#  Value Formatting & SQL Escaping\n# ---------------------------------------------------------------------------\nfunc format_sql_val(val) {\n    if val == nullx {\n        return \"NULL\"\n    }\n    if typeofx(val) == \"string\" {\n        return \"'\" + string.replace(val, \"'\", \"''\") + \"'\"\n    }\n    if typeofx(val) == \"bool\" {\n        if val {\n            return \"1\"\n        }\n        return \"0\"\n    }\n    return \"\" + val\n}\n\n# ---------------------------------------------------------------------------\n#  Global Connection Manager\n# ---------------------------------------------------------------------------\nlet _default_db_conn = nullx\n\nfunc connect(db_path) {\n    _default_db_conn = newx Database(db_path)\n    return _default_db_conn\n}\n\nfunc default_db() {\n    if _default_db_conn == nullx {\n        _default_db_conn = newx Database(\":memory:\")\n    }\n    return _default_db_conn\n}\n\nfunc close_default() {\n    if _default_db_conn != nullx {\n        _default_db_conn.close()\n        _default_db_conn = nullx\n    }\n}\n\nfunc table(tbl_name) {\n    return default_db().table(tbl_name)\n}\n\n# ---------------------------------------------------------------------------\n#  Record (Row Wrapper with Named Columns)\n# ---------------------------------------------------------------------------\nclassx Record {\n    let _table = \"\"\n    let _keys = []\n    let _values = []\n\n    func init(tbl, keys, vals) {\n        this._table = tbl\n        this._keys = keys\n        this._values = vals\n    }\n\n    func get(col) {\n        let i = 0\n        while i < len(this._keys) {\n            if this._keys[i] == col {\n                return this._values[i]\n            }\n            i = i + 1\n        }\n        return nullx\n    }\n\n    func set(col, val) {\n        let i = 0\n        while i < len(this._keys) {\n            if this._keys[i] == col {\n                this._values[i] = val\n                return\n            }\n            i = i + 1\n        }\n        this._keys = this._keys + [col]\n        this._values = this._values + [val]\n    }\n\n    func has(col) {\n        let i = 0\n        while i < len(this._keys) {\n            if this._keys[i] == col {\n                return true\n            }\n            i = i + 1\n        }\n        return false\n    }\n\n    func keys() {\n        return this._keys\n    }\n\n    func values() {\n        return this._values\n    }\n\n    func to_pairs() {\n        let res = []\n        let i = 0\n        while i < len(this._keys) {\n            res = res + [[this._keys[i], this._values[i]]]\n            i = i + 1\n        }\n        return res\n    }\n\n    func to_json() {\n        return json.stringify_pairs(this.to_pairs())\n    }\n}\n\n# ---------------------------------------------------------------------------\n#  QueryBuilder\n# ---------------------------------------------------------------------------\nclassx QueryBuilder {\n    let db = nullx\n    let table_name = \"\"\n    let where_clauses = []\n    let order_col = \"\"\n    let order_dir = \"ASC\"\n    let limit_n = -1\n    let offset_n = -1\n    let select_cols = \"*\"\n\n    func init(db_inst, tbl) {\n        this.db = db_inst\n        this.table_name = tbl\n        this.where_clauses = []\n        this.order_col = \"\"\n        this.order_dir = \"ASC\"\n        this.limit_n = -1\n        this.offset_n = -1\n        this.select_cols = \"*\"\n    }\n\n    func select(cols) {\n        this.select_cols = cols\n        return this\n    }\n\n    func where(col, op, val) {\n        let standard_op = op\n        if op == \"==\" {\n            standard_op = \"=\"\n        }\n        this.where_clauses = this.where_clauses + [[col, standard_op, val]]\n        return this\n    }\n\n    func where_null(col) {\n        this.where_clauses = this.where_clauses + [[col, \"IS\", nullx]]\n        return this\n    }\n\n    func where_not_null(col) {\n        this.where_clauses = this.where_clauses + [[col, \"IS NOT\", nullx]]\n        return this\n    }\n\n    func orderBy(col, dir) {\n        this.order_col = col\n        if dir != nullx {\n            this.order_dir = dir\n        }\n        return this\n    }\n\n    func limit(n) {\n        this.limit_n = n\n        return this\n    }\n\n    func offset(n) {\n        this.offset_n = n\n        return this\n    }\n\n    func build_where_sql() {\n        if len(this.where_clauses) == 0 {\n            return \"\"\n        }\n        let parts = []\n        let i = 0\n        while i < len(this.where_clauses) {\n            let item = this.where_clauses[i]\n            let col = item[0]\n            let op = item[1]\n            let val = item[2]\n            let clause = \"\"\n            if op == \"IS\" || op == \"IS NOT\" {\n                clause = col + \" \" + op + \" NULL\"\n            } else {\n                clause = col + \" \" + op + \" \" + format_sql_val(val)\n            }\n            parts = parts + [clause]\n            i = i + 1\n        }\n        return \" WHERE \" + string.join(parts, \" AND \")\n    }\n\n    func to_sql() {\n        let sql = \"SELECT \" + this.select_cols + \" FROM \" + this.table_name + this.build_where_sql()\n        if this.order_col != \"\" {\n            sql = sql + \" ORDER BY \" + this.order_col + \" \" + this.order_dir\n        }\n        if this.limit_n >= 0 {\n            sql = sql + \" LIMIT \" + (\"\" + this.limit_n)\n        }\n        if this.offset_n >= 0 {\n            sql = sql + \" OFFSET \" + (\"\" + this.offset_n)\n        }\n        return sql\n    }\n\n    func get() {\n        let sql = this.to_sql()\n        let cols = this.db.get_columns(this.table_name)\n        let rows = this.db.query(sql)\n        let records = []\n        let r = 0\n        while r < len(rows) {\n            records = records + [newx Record(this.table_name, cols, rows[r])]\n            r = r + 1\n        }\n        return records\n    }\n\n    func get_pairs() {\n        let recs = this.get()\n        let out = []\n        let i = 0\n        while i < len(recs) {\n            out = out + [recs[i].to_pairs()]\n            i = i + 1\n        }\n        return out\n    }\n\n    func first() {\n        this.limit(1)\n        let recs = this.get()\n        if len(recs) == 0 {\n            return nullx\n        }\n        return recs[0]\n    }\n\n    func find(id) {\n        this.where(\"id\", \"==\", id)\n        return this.first()\n    }\n\n    func count() {\n        let sql = \"SELECT COUNT(*) FROM \" + this.table_name + this.build_where_sql()\n        let rows = this.db.query(sql)\n        if len(rows) > 0 && len(rows[0]) > 0 {\n            return rows[0][0]\n        }\n        return 0\n    }\n\n    func pluck(col) {\n        let recs = this.get()\n        let out = []\n        let i = 0\n        while i < len(recs) {\n            out = out + [recs[i].get(col)]\n            i = i + 1\n        }\n        return out\n    }\n\n    func insert(pairs) {\n        let cols = []\n        let vals = []\n        let i = 0\n        while i < len(pairs) {\n            cols = cols + [pairs[i][0]]\n            vals = vals + [format_sql_val(pairs[i][1])]\n            i = i + 1\n        }\n        let sql = \"INSERT INTO \" + this.table_name + \" (\" + string.join(cols, \", \") + \") VALUES (\" + string.join(vals, \", \") + \");\"\n        this.db.exec(sql)\n        let id_row = this.db.query(\"SELECT last_insert_rowid();\")\n        if len(id_row) > 0 && len(id_row[0]) > 0 {\n            return id_row[0][0]\n        }\n        return 1\n    }\n\n    func update(pairs) {\n        let set_parts = []\n        let i = 0\n        while i < len(pairs) {\n            let col = pairs[i][0]\n            let val = format_sql_val(pairs[i][1])\n            set_parts = set_parts + [col + \" = \" + val]\n            i = i + 1\n        }\n        let sql = \"UPDATE \" + this.table_name + \" SET \" + string.join(set_parts, \", \") + this.build_where_sql() + \";\"\n        return this.db.exec(sql)\n    }\n\n    func delete() {\n        let sql = \"DELETE FROM \" + this.table_name + this.build_where_sql() + \";\"\n        return this.db.exec(sql)\n    }\n}\n\n# ---------------------------------------------------------------------------\n#  Database Connection\n# ---------------------------------------------------------------------------\nclassx Database {\n    let conn = 0\n    let path = \"\"\n\n    func init(db_path) {\n        this.path = db_path\n        this.conn = db_open(db_path)\n    }\n\n    func close() {\n        if this.conn != 0 {\n            db_close(this.conn)\n            this.conn = 0\n        }\n    }\n\n    func exec(sql) {\n        return db_exec(this.conn, sql)\n    }\n\n    func query(sql) {\n        return db_query(this.conn, sql)\n    }\n\n    func get_columns(tbl) {\n        let rows = this.query(\"PRAGMA table_info(\" + tbl + \");\")\n        let cols = []\n        let i = 0\n        while i < len(rows) {\n            cols = cols + [rows[i][1]]\n            i = i + 1\n        }\n        return cols\n    }\n\n    func table(tbl_name) {\n        return newx QueryBuilder(this, tbl_name)\n    }\n}\n\n# ---------------------------------------------------------------------------\n#  Base Active Record Model\n# ---------------------------------------------------------------------------\nclassx Model {\n    let _table = \"\"\n    let _db = nullx\n\n    func init(tbl, db_inst) {\n        this._table = tbl\n        if db_inst != nullx {\n            this._db = db_inst\n        } else {\n            this._db = default_db()\n        }\n    }\n\n    func query() {\n        return this._db.table(this._table)\n    }\n\n    func all() {\n        return this.query().get()\n    }\n\n    func all_pairs() {\n        return this.query().get_pairs()\n    }\n\n    func find(id) {\n        return this.query().find(id)\n    }\n\n    func where(col, op, val) {\n        return this.query().where(col, op, val)\n    }\n\n    func create(pairs) {\n        let new_id = this.query().insert(pairs)\n        return this.find(new_id)\n    }\n\n    func count() {\n        return this.query().count()\n    }\n}\n";

