/* ---- Module: os (/home/theyad75/Desktop/antmountxlang/shared/stdlib/system/os.mx) ---- */
static const char s_src_os[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# os.mx - filesystem & environment (system/)\n# Needs the os_* natives (Step 2).\n\nimportx string\n\nfunc sep() {\n    return os_sep()\n}\n\nfunc path_join(parts) {\n    return string.join(parts, os_sep())\n}\n\nfunc path_split(p) {\n    return string.split(p, os_sep())\n}\n\nfunc path_basename(p) {\n    let parts = path_split(p)\n    if len(parts) == 0 {\n        return \"\"\n    }\n    return parts[len(parts) - 1]\n}\n\nfunc path_parent(p) {\n    let parts = path_split(p)\n    if len(parts) <= 1 {\n        return \"\"\n    }\n    let out = []\n    let i = 0\n    while i < len(parts) - 1 {\n        out = out + [parts[i]]\n        i = i + 1\n    }\n    return string.join(out, os_sep())\n}\n\n# \"report.txt\" -> \"txt\"; dotfiles like \".mx\" -> \"\"; no dot -> \"\"\nfunc path_ext(p) {\n    let base = path_basename(p)\n    let dot = string.last_index_of(base, \".\")\n    if dot <= 0 {\n        return \"\"\n    }\n    return string.substr(base, dot + 1, len(base))\n}\n\nfunc env(name) {\n    return os_env(name)\n}\n\nfunc env_or(name, fallback) {\n    let v = os_env(name)\n    if v == nullx {\n        return fallback\n    }\n    return v\n}\n\nfunc cwd() {\n    return os_cwd()\n}\n\n# sorted names; throws on a bad path\nfunc listdir(path) {\n    return os_listdir(path)\n}\n\n# entries whose name ends with ext (\".mx\"); ext \"\" returns everything\nfunc listdir_ext(path, ext) {\n    let all = os_listdir(path)\n    if ext == \"\" {\n        return all\n    }\n    let out = []\n    for name in all {\n        if string.ends_with(name, ext) {\n            out = out + [name]\n        }\n    }\n    return out\n}\n\n# run a system command and return its exit code (integer)\nfunc system(cmd) {\n    let raw = sys_exec(cmd)\n    return raw[0]\n}\n";

