static const char s_src_random[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# random.mx - seeded pseudo-random numbers (core/)\n# Same seed -> same sequence (great for reproducible tests). The shared\n# generator is seeded from time_now_ms() when available, else 1.\n\nclassx Rand {\n    let s = 1\n\n    func init(seed) {\n        if seed <= 0 {\n            seed = 7 - seed\n        }\n        this.s = seed\n    }\n\n    # 0 .. 2147483647\n    func next() {\n        this.s = (this.s * 1103515245 + 12345) % 2147483648\n        return this.s\n    }\n\n    # 0 .. n-1\n    func below(n) {\n        if n <= 0 {\n            throwx \"random.below: n must be > 0\"\n        }\n        return this.next() % n\n    }\n\n    func int_between(lo, hi) {\n        if hi <= lo {\n            throwx \"random.int_between: hi must be > lo\"\n        }\n        return lo + this.below(hi - lo)\n    }\n\n    # true pct% of the time\n    func chance(pct) {\n        return this.below(100) < pct\n    }\n\n    func choice(arr) {\n        if len(arr) == 0 {\n            throwx \"random.choice: empty array\"\n        }\n        return arr[this.below(len(arr))]\n    }\n\n    # in-place Fisher-Yates; returns the same array\n    func shuffle(arr) {\n        let i = len(arr) - 1\n        while i > 0 {\n            let j = this.below(i + 1)\n            let tmp = arr[i]\n            arr[i] = arr[j]\n            arr[j] = tmp\n            i = i - 1\n        }\n        return arr\n    }\n}\n\n# ---- shared generator ----\n# One documented module-level let with a _-prefixed name (module lets become\n# globals; the underscore keeps it collision-free, and imports run once).\nlet _default_rng = newx Rand(1)\ntryx {\n    _default_rng = newx Rand(time_now_ms())\n} catchx(e) {\n}\n\nfunc seed_rng(seed) {\n    _default_rng = newx Rand(seed)\n    return true\n}\n\nfunc rand_below(n)    { return _default_rng.below(n) }\nfunc rand_int(lo, hi) { return _default_rng.int_between(lo, hi) }\nfunc rand_choice(arr) { return _default_rng.choice(arr) }\nfunc rand_shuffle(arr) { return _default_rng.shuffle(arr) }\nfunc rand_chance(pct) { return _default_rng.chance(pct) }\n";

