static const char s_src_regex[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# regex.mx - regular expression pattern matcher (text/)\n# Supports:\n#   .    any character\n#   ^    start of string\n#   $    end of string\n#   *    zero or more of previous element\n#   +    one or more of previous element\n#   ?    zero or one of previous element\n#   [abc] character class / range [a-z], [0-9]\n#   [^abc] negated character class\n#\n# Usage:\n#   importx regex\n#   regex.is_match(\"^hello\", \"hello world\") # true\n#   regex.is_match(\"a+b\", \"aaab\")           # true\n#   regex.is_match(\"[0-9]+\", \"12345\")       # true\n\nimportx string\n\n# Compiles pattern into token structures:\n# Each token: [type, char_val, quantifier]\n# type: \"CHAR\", \"DOT\", \"CLASS\", \"NEG_CLASS\"\n# quantifier: \"ONE\", \"STAR\", \"PLUS\", \"OPT\"\nfunc _compile_pattern(pat) {\n    let tokens = []\n    let i = 0\n    let n = len(pat)\n\n    while i < n {\n        let ch = pat[i]\n        let tok_type = \"CHAR\"\n        let tok_val = ch\n\n        if ch == \".\" {\n            tok_type = \"DOT\"\n            tok_val = \".\"\n        } else if ch == \"[\" {\n            let close_bracket = string.index_of(string.substr(pat, i + 1, n), \"]\")\n            if close_bracket >= 0 {\n                let inside = string.substr(pat, i + 1, i + 1 + close_bracket)\n                i = i + 1 + close_bracket\n                if string.starts_with(inside, \"^\") {\n                    tok_type = \"NEG_CLASS\"\n                    tok_val = string.substr(inside, 1, len(inside))\n                } else {\n                    tok_type = \"CLASS\"\n                    tok_val = inside\n                }\n            }\n        }\n\n        # Check for quantifier in next char\n        let quant = \"ONE\"\n        if i + 1 < n {\n            let next_ch = pat[i + 1]\n            if next_ch == \"*\" {\n                quant = \"STAR\"\n                i = i + 1\n            } else if next_ch == \"+\" {\n                quant = \"PLUS\"\n                i = i + 1\n            } else if next_ch == \"?\" {\n                quant = \"OPT\"\n                i = i + 1\n            }\n        }\n\n        tokens = tokens + [[tok_type, tok_val, quant]]\n        i = i + 1\n    }\n    return tokens\n}\n\nfunc _match_one_char(tok, ch) {\n    let tok_type = tok[0]\n    let tok_val = tok[1]\n\n    if tok_type == \"DOT\" {\n        return true\n    }\n    if tok_type == \"CHAR\" {\n        return tok_val == ch\n    }\n    if tok_type == \"CLASS\" || tok_type == \"NEG_CLASS\" {\n        let matched = false\n        let j = 0\n        let len_val = len(tok_val)\n        while j < len_val {\n            if j + 2 < len_val && tok_val[j + 1] == \"-\" {\n                let start_ch = tok_val[j]\n                let end_ch = tok_val[j + 2]\n                if ch >= start_ch && ch <= end_ch {\n                    matched = true\n                    break\n                }\n                j = j + 3\n            } else {\n                if tok_val[j] == ch {\n                    matched = true\n                    break\n                }\n                j = j + 1\n            }\n        }\n        if tok_type == \"NEG_CLASS\" {\n            return !matched\n        }\n        return matched\n    }\n    return false\n}\n\nfunc _match_tokens(tokens, t_idx, text, s_idx) {\n    if t_idx >= len(tokens) {\n        return true\n    }\n\n    let tok = tokens[t_idx]\n    let quant = tok[2]\n\n    if quant == \"ONE\" {\n        if s_idx >= len(text) {\n            return false\n        }\n        if _match_one_char(tok, text[s_idx]) {\n            return _match_tokens(tokens, t_idx + 1, text, s_idx + 1)\n        }\n        return false\n    }\n\n    if quant == \"OPT\" {\n        # Try matching 1 char\n        if s_idx < len(text) && _match_one_char(tok, text[s_idx]) {\n            if _match_tokens(tokens, t_idx + 1, text, s_idx + 1) {\n                return true\n            }\n        }\n        # Or match 0 chars\n        return _match_tokens(tokens, t_idx + 1, text, s_idx)\n    }\n\n    if quant == \"STAR\" {\n        # Greedily match 0 or more\n        let cur = s_idx\n        while cur < len(text) && _match_one_char(tok, text[cur]) {\n            cur = cur + 1\n        }\n        # Backtrack\n        while cur >= s_idx {\n            if _match_tokens(tokens, t_idx + 1, text, cur) {\n                return true\n            }\n            cur = cur - 1\n        }\n        return false\n    }\n\n    if quant == \"PLUS\" {\n        if s_idx >= len(text) || !_match_one_char(tok, text[s_idx]) {\n            return false\n        }\n        let cur = s_idx + 1\n        while cur < len(text) && _match_one_char(tok, text[cur]) {\n            cur = cur + 1\n        }\n        while cur > s_idx {\n            if _match_tokens(tokens, t_idx + 1, text, cur) {\n                return true\n            }\n            cur = cur - 1\n        }\n        return false\n    }\n\n    return false\n}\n\nfunc is_match(pat, text) {\n    let p = pat\n    let anchor_start = false\n    let anchor_end = false\n\n    if string.starts_with(p, \"^\") {\n        anchor_start = true\n        p = string.substr(p, 1, len(p))\n    }\n    if string.ends_with(p, \"$\") {\n        anchor_end = true\n        p = string.substr(p, 0, len(p) - 1)\n    }\n\n    let tokens = _compile_pattern(p)\n\n    if anchor_start {\n        if anchor_end {\n            # Must match exact whole string\n            let i = 0\n            while i <= len(text) {\n                if _match_tokens(tokens, 0, text, 0) {\n                    # verify text fully consumed\n                    let len_matched = _match_length(tokens, text, 0)\n                    if len_matched == len(text) {\n                        return true\n                    }\n                }\n                return false\n            }\n        }\n        return _match_tokens(tokens, 0, text, 0)\n    }\n\n    let s = 0\n    while s <= len(text) {\n        if _match_tokens(tokens, 0, text, s) {\n            if anchor_end {\n                let len_m = _match_length(tokens, text, s)\n                if s + len_m == len(text) {\n                    return true\n                }\n            } else {\n                return true\n            }\n        }\n        s = s + 1\n    }\n    return false\n}\n\nfunc _match_length(tokens, text, s_idx) {\n    let s = s_idx\n    let t = 0\n    while t < len(tokens) && s < len(text) {\n        let tok = tokens[t]\n        let quant = tok[2]\n        if quant == \"ONE\" {\n            if _match_one_char(tok, text[s]) {\n                s = s + 1\n            } else {\n                return -1\n            }\n        } else if quant == \"STAR\" || quant == \"PLUS\" {\n            while s < len(text) && _match_one_char(tok, text[s]) {\n                s = s + 1\n            }\n        } else if quant == \"OPT\" {\n            if s < len(text) && _match_one_char(tok, text[s]) {\n                s = s + 1\n            }\n        }\n        t = t + 1\n    }\n    return s - s_idx\n}\n\nfunc match_find(pat, text) {\n    let tokens = _compile_pattern(pat)\n    let s = 0\n    while s < len(text) {\n        if _match_tokens(tokens, 0, text, s) {\n            let m_len = _match_length(tokens, text, s)\n            if m_len >= 0 {\n                return string.substr(text, s, s + m_len)\n            }\n        }\n        s = s + 1\n    }\n    return nullx\n}\n\nfunc find(pat, text) {\n    return match_find(pat, text)\n}\n\nfunc replace(pat, repl, text) {\n    let found = match_find(pat, text)\n    if found == nullx {\n        return text\n    }\n    return string.replace(text, found, repl)\n}\n";

