static const char s_src_set[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# set.mx - Set class (array-backed; == is deep equality for members)\n\nclassx Set {\n    let keys = []\n\n    func add(v) {\n        if !this.has(v) {\n            this.keys = this.keys + [v]\n        }\n        return this\n    }\n\n    func add_all(arr) {\n        for v in arr {\n            this.add(v)\n        }\n        return this\n    }\n\n    func has(v) {\n        let i = 0\n        while i < len(this.keys) {\n            if this.keys[i] == v {\n                return true\n            }\n            i = i + 1\n        }\n        return false\n    }\n\n    func remove(v) {\n        let out = []\n        let found = false\n        for x in this.keys {\n            if x == v {\n                found = true\n            } else {\n                out = out + [x]\n            }\n        }\n        this.keys = out\n        return found\n    }\n\n    func size() {\n        return len(this.keys)\n    }\n\n    func is_empty() {\n        return len(this.keys) == 0\n    }\n\n    func clear() {\n        this.keys = []\n    }\n\n    func to_array() {\n        return this.keys + []\n    }\n\n    func union(other) {\n        let s = newx Set()\n        s.add_all(this.keys)\n        s.add_all(other.keys)\n        return s\n    }\n\n    func intersection(other) {\n        let s = newx Set()\n        for v in this.keys {\n            if other.has(v) {\n                s.add(v)\n            }\n        }\n        return s\n    }\n\n    # members of this set not in other\n    func difference(other) {\n        let s = newx Set()\n        for v in this.keys {\n            if !other.has(v) {\n                s.add(v)\n            }\n        }\n        return s\n    }\n\n    func is_subset(other) {\n        for v in this.keys {\n            if !other.has(v) {\n                return false\n            }\n        }\n        return true\n    }\n\n    func equals(other) {\n        if this.size() != other.size() {\n            return false\n        }\n        return this.is_subset(other)\n    }\n}\n";

