static const char s_src_socket[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# socket.mx - TCP Socket networking for MountX (system/)\n# Backed by native tcp_* builtins in host and native substrate.\n\nfunc listen(port, host) {\n    if host == nullx {\n        return tcp_listen(port, \"0.0.0.0\")\n    }\n    return tcp_listen(port, host)\n}\n\nfunc accept(server_fd) {\n    return tcp_accept(server_fd)\n}\n\nfunc recv(client_ref, max_len) {\n    let fd = client_ref\n    if typeofx(client_ref) == \"array\" {\n        fd = client_ref[0]\n    }\n    if max_len == nullx {\n        return tcp_recv(fd, 4096)\n    }\n    return tcp_recv(fd, max_len)\n}\n\nfunc send(client_ref, data) {\n    let fd = client_ref\n    if typeofx(client_ref) == \"array\" {\n        fd = client_ref[0]\n    }\n    return tcp_send(fd, data)\n}\n\nfunc close(client_ref) {\n    let fd = client_ref\n    if typeofx(client_ref) == \"array\" {\n        fd = client_ref[0]\n    }\n    return tcp_close(fd)\n}\n\nfunc connect(host, port) {\n    if host == nullx {\n        return tcp_connect(\"127.0.0.1\", port)\n    }\n    return tcp_connect(host, port)\n}\n\nclassx TcpServer {\n    func init(port, host) {\n        this.port = port\n        if host == nullx {\n            this.host = \"0.0.0.0\"\n        } else {\n            this.host = host\n        }\n        this.fd = nullx\n        this.start()\n    }\n\n    func start() {\n        if this.fd == nullx {\n            this.fd = tcp_listen(this.port, this.host)\n        }\n        return this\n    }\n\n    func accept() {\n        if this.fd == nullx {\n            this.start()\n        }\n        return tcp_accept(this.fd)\n    }\n\n    func close() {\n        if this.fd != nullx {\n            tcp_close(this.fd)\n            this.fd = nullx\n        }\n    }\n}\n\nclassx TcpClient {\n    func init(host, port) {\n        if host == nullx {\n            this.host = \"127.0.0.1\"\n        } else {\n            this.host = host\n        }\n        this.port = port\n        this.fd = nullx\n    }\n\n    func connect() {\n        if this.fd == nullx {\n            this.fd = tcp_connect(this.host, this.port)\n        }\n        return this\n    }\n\n    func send(data) {\n        if this.fd == nullx {\n            this.connect()\n        }\n        return tcp_send(this.fd, data)\n    }\n\n    func recv(max_len) {\n        if this.fd == nullx {\n            this.connect()\n        }\n        if max_len == nullx {\n            return tcp_recv(this.fd, 4096)\n        }\n        return tcp_recv(this.fd, max_len)\n    }\n\n    func close() {\n        if this.fd != nullx {\n            tcp_close(this.fd)\n            this.fd = nullx\n        }\n    }\n}\n";

