static const char s_src_string[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# string.mx - full string toolkit (replaces the old placeholder version)\n\nfunc tostr(v) {\n    return \"\" + v\n}\n\nfunc is_empty(s) {\n    return len(s) == 0\n}\n\nfunc index_of(s, target) {\n    let n = len(s)\n    let m = len(target)\n    if m == 0 {\n        return 0\n    }\n    let i = 0\n    while i <= n - m {\n        let j = 0\n        let ok = true\n        while j < m {\n            if s[i + j] != target[j] {\n                ok = false\n                break\n            }\n            j = j + 1\n        }\n        if ok {\n            return i\n        }\n        i = i + 1\n    }\n    return -1\n}\n\nfunc last_index_of(s, target) {\n    let n = len(s)\n    let m = len(target)\n    if m == 0 {\n        return n\n    }\n    if m > n {\n        return -1\n    }\n    let i = n - m\n    while i >= 0 {\n        let j = 0\n        let ok = true\n        while j < m {\n            if s[i + j] != target[j] {\n                ok = false\n                break\n            }\n            j = j + 1\n        }\n        if ok {\n            return i\n        }\n        i = i - 1\n    }\n    return -1\n}\n\nfunc contains(s, sub) {\n    return index_of(s, sub) != -1\n}\n\nfunc starts_with(s, prefix) {\n    if len(prefix) > len(s) {\n        return false\n    }\n    let i = 0\n    while i < len(prefix) {\n        if s[i] != prefix[i] {\n            return false\n        }\n        i = i + 1\n    }\n    return true\n}\n\nfunc ends_with(s, suffix) {\n    if len(suffix) > len(s) {\n        return false\n    }\n    let offset = len(s) - len(suffix)\n    let i = 0\n    while i < len(suffix) {\n        if s[offset + i] != suffix[i] {\n            return false\n        }\n        i = i + 1\n    }\n    return true\n}\n\n# end-exclusive; clamps to the string\nfunc substr(s, start, end) {\n    if start < 0 {\n        start = 0\n    }\n    if end > len(s) {\n        end = len(s)\n    }\n    let out = \"\"\n    let i = start\n    while i < end {\n        out = out + s[i]\n        i = i + 1\n    }\n    return out\n}\n\nfunc split(s, sep) {\n    let out = []\n    if sep == \"\" {\n        let chars = []\n        let i = 0\n        while i < len(s) {\n            chars = chars + [s[i]]\n            i = i + 1\n        }\n        return chars\n    }\n    let rest = s\n    while true {\n        let pos = index_of(rest, sep)\n        if pos == -1 {\n            out = out + [rest]\n            break\n        }\n        out = out + [substr(rest, 0, pos)]\n        rest = substr(rest, pos + len(sep), len(rest))\n    }\n    return out\n}\n\nfunc join(arr, sep) {\n    let out = \"\"\n    let i = 0\n    while i < len(arr) {\n        if i > 0 {\n            out = out + sep\n        }\n        out = out + arr[i]\n        i = i + 1\n    }\n    return out\n}\n\nfunc _is_ws(ch) {\n    return ch == \" \" || ch == \"\\t\" || ch == \"\\n\" || ch == \"\\r\"\n}\n\nfunc trim_start(s) {\n    let i = 0\n    while i < len(s) {\n        if !_is_ws(s[i]) {\n            break\n        }\n        i = i + 1\n    }\n    return substr(s, i, len(s))\n}\n\nfunc trim_end(s) {\n    let end = len(s)\n    while end > 0 {\n        if !_is_ws(s[end - 1]) {\n            break\n        }\n        end = end - 1\n    }\n    return substr(s, 0, end)\n}\n\nfunc trim(s) {\n    return trim_end(trim_start(s))\n}\n\n# replaces ALL occurrences; \"from\" must not be \"\"\nfunc replace_all(s, from, to) {\n    if from == \"\" {\n        return s\n    }\n    let out = \"\"\n    let rest = s\n    while true {\n        let pos = index_of(rest, from)\n        if pos == -1 {\n            out = out + rest\n            break\n        }\n        out = out + substr(rest, 0, pos) + to\n        rest = substr(rest, pos + len(from), len(rest))\n    }\n    return out\n}\n\nfunc replace(s, from, to) {\n    return replace_all(s, from, to)\n}\n\nfunc repeat(s, n) {\n    let out = \"\"\n    loop n {\n        out = out + s\n    }\n    return out\n}\n\nfunc reverse(s) {\n    let out = \"\"\n    let i = len(s) - 1\n    while i >= 0 {\n        out = out + s[i]\n        i = i - 1\n    }\n    return out\n}\n\nfunc upper(s) {\n    let lo = \"abcdefghijklmnopqrstuvwxyz\"\n    let up = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n    let out = \"\"\n    let i = 0\n    while i < len(s) {\n        let idx = index_of(lo, s[i])\n        if idx >= 0 {\n            out = out + up[idx]\n        } else {\n            out = out + s[i]\n        }\n        i = i + 1\n    }\n    return out\n}\n\nfunc lower(s) {\n    let lo = \"abcdefghijklmnopqrstuvwxyz\"\n    let up = \"ABCDEFGHIJKLMNOPQRSTUVWXYZ\"\n    let out = \"\"\n    let i = 0\n    while i < len(s) {\n        let idx = index_of(up, s[i])\n        if idx >= 0 {\n            out = out + lo[idx]\n        } else {\n            out = out + s[i]\n        }\n        i = i + 1\n    }\n    return out\n}\n\nfunc to_lower(s) {\n    return lower(s)\n}\n\nfunc to_upper(s) {\n    return upper(s)\n}\n\nfunc capitalize(s) {\n    if len(s) == 0 {\n        return s\n    }\n    return upper(s[0]) + substr(s, 1, len(s))\n}\n\n# pads with whole copies of pad; may exceed width to keep pad intact\nfunc pad_start(s, width, pad) {\n    let out = s\n    while len(out) < width {\n        out = pad + out\n    }\n    return out\n}\n\nfunc pad_end(s, width, pad) {\n    let out = s\n    while len(out) < width {\n        out = out + pad\n    }\n    return out\n}\n\n# non-overlapping occurrence count; 0 when sub is \"\"\nfunc count(s, sub) {\n    if sub == \"\" {\n        return 0\n    }\n    let n = 0\n    let rest = s\n    while true {\n        let pos = index_of(rest, sub)\n        if pos == -1 {\n            break\n        }\n        n = n + 1\n        rest = substr(rest, pos + len(sub), len(rest))\n    }\n    return n\n}\n\n# \"42\" -> 42, \" -1.5 \" -> -1.5, \"abc\" -> nullx\nfunc tonum(s) {\n    let dg = \"0123456789\"\n    let t = trim(s)\n    let n = len(t)\n    if n == 0 {\n        return nullx\n    }\n    let i = 0\n    let neg = false\n    if t[0] == \"-\" {\n        neg = true\n        i = 1\n    } else if t[0] == \"+\" {\n        i = 1\n    }\n    if i >= n {\n        return nullx\n    }\n    let intpart = 0\n    let fracval = 0\n    let frac_count = 0\n    let seen_dot = false\n    let any = false\n    while i < n {\n        let ch = t[i]\n        if ch == \".\" {\n            if seen_dot {\n                return nullx\n            }\n            seen_dot = true\n        } else {\n            let d = index_of(dg, ch)\n            if d < 0 {\n                return nullx\n            }\n            any = true\n            if seen_dot {\n                fracval = fracval * 10 + d\n                frac_count = frac_count + 1\n            } else {\n                intpart = intpart * 10 + d\n            }\n        }\n        i = i + 1\n    }\n    if !any {\n        return nullx\n    }\n    let v = intpart\n    if frac_count > 0 {\n        let p = 1\n        let k = 0\n        while k < frac_count {\n            p = p * 10\n            k = k + 1\n        }\n        v = intpart + fracval / p\n    }\n    if neg {\n        return 0 - v\n    }\n    return v\n}\n";

