/* ---- Module: sys (/home/theyad75/Desktop/antmountxlang/shared/stdlib/system/sys.mx) ---- */
static const char s_src_sys[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# sys.mx - command line & process (system/)\n# Needs the sys_args / sys_exit natives.\n#   python3 main.py prog.mx --name Ada -v data.txt\n#   -> sys.args() == [\"--name\", \"Ada\", \"-v\", \"data.txt\"]\n\nimportx string\n\nfunc args() {\n    return sys_args()\n}\n\n# exits the process immediately; NOT catchable by tryx/catchx\nfunc exit(code) {\n    sys_exit(code)\n    return nullx\n}\n\nfunc version() {\n    return \"mountx stdlib 1.0\"\n}\n\n# [\"--name\", \"Ada\", \"-v\", \"x.txt\"] -> [named_pairs, flags, positional]\nfunc parse_args(argv) {\n    let named = []\n    let flags = []\n    let positional = []\n    let i = 0\n    while i < len(argv) {\n        let a = argv[i]\n        if string.starts_with(a, \"--\") {\n            let body = string.substr(a, 2, len(a))\n            let eq = string.index_of(body, \"=\")\n            if eq >= 0 {\n                named = named + [[string.substr(body, 0, eq), string.substr(body, eq + 1, len(body))]]\n            } else {\n                flags = flags + [body]\n            }\n        } else if string.starts_with(a, \"-\") && a != \"-\" {\n            flags = flags + [string.substr(a, 1, len(a))]\n        } else {\n            positional = positional + [a]\n        }\n        i = i + 1\n    }\n    return [named, flags, positional]\n}\n\nfunc arg_named(parsed, name) {\n    for p in parsed[0] {\n        if p[0] == name {\n            return p[1]\n        }\n    }\n    return nullx\n}\n\nfunc has_flag(parsed, flag) {\n    for f in parsed[1] {\n        if f == flag {\n            return true\n        }\n    }\n    return false\n}\n\nfunc positional_args(parsed) {\n    return parsed[2]\n}\n";

