static const char s_src_time[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# time.mx - clocks, dates, durations (system/)\n# Needs the time_now_ms / sleep_ms natives (Step 2). Dates are UTC.\n\nimportx mathfull\n\nfunc now_ms() {\n    return time_now_ms()\n}\n\nfunc sleep(ms) {\n    return sleep_ms(ms)\n}\n\n# floor division via Python-style % (remainder of a % b is >= 0 for b > 0)\nfunc _fdiv(a, b) {\n    let r = a % b\n    return mathfull.idiv(a - r, b)\n}\n\n# [year, month, day, hour, minute, second, ms] in UTC, from epoch ms.\n# Works for pre-1970 timestamps too (negative epoch).\nfunc date_parts(epoch_ms) {\n    let secs = _fdiv(epoch_ms, 1000)\n    let ms = epoch_ms - secs * 1000\n    let days = _fdiv(secs, 86400)\n    let rem = secs - days * 86400\n    let hh = mathfull.idiv(rem, 3600)\n    rem = rem - hh * 3600\n    let mm = mathfull.idiv(rem, 60)\n    let ss = rem - mm * 60\n\n    # days-since-epoch -> civil date (Hinnant's algorithm)\n    let z = days + 719468\n    let doe = z % 146097\n    let era = mathfull.idiv(z - doe, 146097)\n    let yoe = mathfull.idiv(doe - mathfull.idiv(doe, 1460) + mathfull.idiv(doe, 36524) - mathfull.idiv(doe, 146096), 365)\n    let y = yoe + era * 400\n    let doy = doe - (365 * yoe + mathfull.idiv(yoe, 4) - mathfull.idiv(yoe, 100))\n    let mp = mathfull.idiv(5 * doy + 2, 153)\n    let d = doy - mathfull.idiv(153 * mp + 2, 5) + 1\n    let m = mp + 3\n    if mp >= 10 {\n        m = mp - 9\n    }\n    if m <= 2 {\n        y = y + 1\n    }\n    return [y, m, d, hh, mm, ss, ms]\n}\n\nfunc _pad2(n) {\n    if n < 10 {\n        return \"0\" + n\n    }\n    return \"\" + n\n}\n\nfunc _pad3(n) {\n    if n < 10  { return \"00\" + n }\n    if n < 100 { return \"0\" + n }\n    return \"\" + n\n}\n\n# \"2025-01-07 14:03:09\"\nfunc format_date(epoch_ms) {\n    let p = date_parts(epoch_ms)\n    return \"\" + p[0] + \"-\" + _pad2(p[1]) + \"-\" + _pad2(p[2]) + \" \" + _pad2(p[3]) + \":\" + _pad2(p[4]) + \":\" + _pad2(p[5])\n}\n\n# 3723456 -> \"1h 2m 3.456s\"\nfunc format_duration(ms) {\n    let neg = false\n    if ms < 0 {\n        neg = true\n        ms = 0 - ms\n    }\n    let out = \"\"\n    let h = mathfull.idiv(ms, 3600000)\n    let rem = ms - h * 3600000\n    let m = mathfull.idiv(rem, 60000)\n    rem = rem - m * 60000\n    let s = mathfull.idiv(rem, 1000)\n    rem = rem - s * 1000\n    if h > 0 {\n        out = out + h + \"h \"\n    }\n    if m > 0 {\n        out = out + m + \"m \"\n    }\n    out = out + s + \".\" + _pad3(rem) + \"s\"\n    if neg {\n        return \"-\" + out\n    }\n    return out\n}\n\nclassx Stopwatch {\n    let start_ms = 0\n    let running = false\n    let elapsed_ms = 0\n\n    func init() {\n        this.start_ms = now_ms()\n        this.running = true\n    }\n\n    func stop() {\n        if this.running {\n            this.elapsed_ms = now_ms() - this.start_ms\n            this.running = false\n        }\n        return this.elapsed_ms\n    }\n\n    func restart() {\n        this.start_ms = now_ms()\n        this.elapsed_ms = 0\n        this.running = true\n        return this\n    }\n\n    func peek() {\n        if this.running {\n            return now_ms() - this.start_ms\n        }\n        return this.elapsed_ms\n    }\n\n    func report() {\n        return format_duration(this.peek())\n    }\n}\n";

