static const char s_src_tuple[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# tuple.mx - immutable sequence data structure (data/)\n# Usage:\n#   importx tuple\n#   let t = tuple.create([1, \"a\", true])\n#   t.get(0)        # 1\n#   t.len()         # 3\n#   t.contains(\"a\") # true\n\nimportx string\n\nclassx Tuple {\n    let _data = []\n\n    func init(items) {\n        this._data = []\n        if items != nullx {\n            for x in items {\n                this._data = this._data + [x]\n            }\n        }\n    }\n\n    func get(idx) {\n        if idx < 0 || idx >= len(this._data) {\n            throwx \"Tuple index out of range: \" + idx\n        }\n        return this._data[idx]\n    }\n\n    func size() {\n        return len(this._data)\n    }\n\n    func to_array() {\n        let copy = []\n        for x in this._data {\n            copy = copy + [x]\n        }\n        return copy\n    }\n\n    func contains(val) {\n        for x in this._data {\n            if x == val {\n                return true\n            }\n        }\n        return false\n    }\n\n    func index_of(val) {\n        let i = 0\n        while i < len(this._data) {\n            if this._data[i] == val {\n                return i\n            }\n            i = i + 1\n        }\n        return -1\n    }\n\n    func slice(start, end) {\n        let s = start\n        let e = end\n        if s < 0 { s = 0 }\n        if e > len(this._data) { e = len(this._data) }\n        let sub = []\n        let i = s\n        while i < e {\n            sub = sub + [this._data[i]]\n            i = i + 1\n        }\n        return newx Tuple(sub)\n    }\n\n    func concat(other) {\n        let combined = []\n        for x in this._data {\n            combined = combined + [x]\n        }\n        let other_arr = other.to_array()\n        for y in other_arr {\n            combined = combined + [y]\n        }\n        return newx Tuple(combined)\n    }\n\n    func to_string() {\n        let strs = []\n        for x in this._data {\n            strs = strs + [\"\" + x]\n        }\n        return \"(\" + string.join(strs, \", \") + \")\"\n    }\n}\n\nfunc create(items) {\n    return newx Tuple(items)\n}\n";

