static const char s_src_type[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# type.mx - type inspection & conversion (core/)\n# Built on typeofx + the language's truthiness rules. No imports.\n\nfunc is_null(v)      { return typeofx(v) == \"null\" }\nfunc is_bool(v)      { return typeofx(v) == \"bool\" }\nfunc is_int(v)       { return typeofx(v) == \"int\" }\nfunc is_float(v)     { return typeofx(v) == \"float\" }\nfunc is_num(v)       { let t = typeofx(v)  return t == \"int\" || t == \"float\" }\nfunc is_string(v)    { return typeofx(v) == \"string\" }\nfunc is_array(v)     { return typeofx(v) == \"array\" }\nfunc is_function(v)  { return typeofx(v) == \"function\" }\nfunc is_module(v)    { return typeofx(v) == \"module\" }\n\n# instances report their CLASS name, so: is_instance(p, \"Point\")\nfunc is_instance(v, class_name) {\n    return typeofx(v) == class_name\n}\n\n# replicates interpreter truthiness: null/false/0/\"\"/[] are falsy\nfunc to_bool(v) {\n    if v == nullx { return false }\n    if v == false { return false }\n    if v == 0     { return false }\n    if v == \"\"    { return false }\n    if v == []    { return false }\n    return true\n}\n\n# arrays are references; this makes a fully independent copy\nfunc deep_copy(v) {\n    if typeofx(v) == \"array\" {\n        let out = []\n        for x in v {\n            out = out + [deep_copy(x)]\n        }\n        return out\n    }\n    return v\n}\n\n# natural \"empty\" value for each type name\nfunc default_value(type_name) {\n    if type_name == \"bool\"   { return false }\n    if type_name == \"int\"    { return 0 }\n    if type_name == \"float\"  { return 0 }\n    if type_name == \"string\" { return \"\" }\n    if type_name == \"array\"  { return [] }\n    return nullx\n}\n";

