static const char s_src_url[] = "# Copyright (C) 2026-2027 Ziad Mohsin. All Rights Reserved.\n# url.mx - URL parsing and percent encoding (system/)\n# Usage:\n#   importx url\n#   let u = url.parse(\"https://example.com:8080/path/to/page?user=ada&lang=mx#top\")\n#   u.scheme        # \"https\"\n#   u.host          # \"example.com\"\n#   u.port          # 8080\n#   u.path          # \"/path/to/page\"\n#   u.param(\"user\") # \"ada\"\n#   u.fragment      # \"top\"\n\nimportx string\nimportx dict\n\nlet _HEX_DIGITS = \"0123456789ABCDEF\"\n\nfunc _is_hex_digit(c) {\n    return (c >= \"0\" && c <= \"9\") || (c >= \"a\" && c <= \"f\") || (c >= \"A\" && c <= \"F\")\n}\n\nfunc _hex_to_int(c) {\n    let d = string.index_of(\"0123456789\", c)\n    if d >= 0 { return d }\n    if c == \"a\" || c == \"A\" { return 10 }\n    if c == \"b\" || c == \"B\" { return 11 }\n    if c == \"c\" || c == \"C\" { return 12 }\n    if c == \"d\" || c == \"D\" { return 13 }\n    if c == \"e\" || c == \"E\" { return 14 }\n    if c == \"f\" || c == \"F\" { return 15 }\n    return 0\n}\n\nfunc url_decode(s) {\n    let out = \"\"\n    let i = 0\n    let n = len(s)\n    while i < n {\n        let ch = s[i]\n        if ch == \"+\" {\n            out = out + \" \"\n            i = i + 1\n        } else if ch == \"%\" && i + 2 < n {\n            let h1 = s[i + 1]\n            let h2 = s[i + 2]\n            if _is_hex_digit(h1) && _is_hex_digit(h2) {\n                let code = (_hex_to_int(h1) * 16) + _hex_to_int(h2)\n                out = out + str_chr(code)\n                i = i + 3\n            } else {\n                out = out + ch\n                i = i + 1\n            }\n        } else {\n            out = out + ch\n            i = i + 1\n        }\n    }\n    return out\n}\n\nfunc url_encode(s) {\n    let out = \"\"\n    let i = 0\n    let n = len(s)\n    while i < n {\n        let ch = s[i]\n        if (ch >= \"a\" && ch <= \"z\") || (ch >= \"A\" && ch <= \"Z\") ||\n           (ch >= \"0\" && ch <= \"9\") || ch == \"-\" || ch == \"_\" || ch == \".\" || ch == \"~\" {\n            out = out + ch\n        } else {\n            let code = str_ord(ch)\n            let hi = idiv(code, 16)\n            let lo = code % 16\n            out = out + \"%\" + _HEX_DIGITS[hi] + _HEX_DIGITS[lo]\n        }\n        i = i + 1\n    }\n    return out\n}\n\nclassx URL {\n    let scheme = \"\"\n    let host = \"\"\n    let port = 0\n    let path = \"\"\n    let query = \"\"\n    let fragment = \"\"\n    let _params = nullx\n\n    func init(scheme, host, port, path, query, fragment) {\n        this.scheme = scheme\n        this.host = host\n        this.port = port\n        this.path = path\n        this.query = query\n        this.fragment = fragment\n        this._params = newx dict.Dict()\n\n        if query != \"\" {\n            let pairs = string.split(query, \"&\")\n            for p in pairs {\n                let eq = string.index_of(p, \"=\")\n                if eq >= 0 {\n                    let k = string.substr(p, 0, eq)\n                    let v = string.substr(p, eq + 1, len(p))\n                    this._params.set(url_decode(k), url_decode(v))\n                } else if p != \"\" {\n                    this._params.set(url_decode(p), \"\")\n                }\n            }\n        }\n    }\n\n    func query_param(key) {\n        if this._params.has(key) {\n            return this._params.get(key)\n        }\n        return nullx\n    }\n\n    func param(key) {\n        return this.query_param(key)\n    }\n\n    func params() {\n        return this._params\n    }\n\n    func to_string() {\n        let res = \"\"\n        if this.scheme != \"\" {\n            res = res + this.scheme + \"://\"\n        }\n        res = res + this.host\n        if this.port > 0 {\n            res = res + \":\" + this.port\n        }\n        res = res + this.path\n        if this.query != \"\" {\n            res = res + \"?\" + this.query\n        }\n        if this.fragment != \"\" {\n            res = res + \"#\" + this.fragment\n        }\n        return res\n    }\n}\n\nfunc parse_url(url_str) {\n    let s = url_str\n    let scheme = \"\"\n    let host = \"\"\n    let port = 0\n    let path = \"/\"\n    let query = \"\"\n    let fragment = \"\"\n\n    # Scheme\n    let colon_slash = string.index_of(s, \"://\")\n    if colon_slash >= 0 {\n        scheme = string.substr(s, 0, colon_slash)\n        s = string.substr(s, colon_slash + 3, len(s))\n    }\n\n    # Fragment #\n    let hash_idx = string.index_of(s, \"#\")\n    if hash_idx >= 0 {\n        fragment = string.substr(s, hash_idx + 1, len(s))\n        s = string.substr(s, 0, hash_idx)\n    }\n\n    # Query ?\n    let q_idx = string.index_of(s, \"?\")\n    if q_idx >= 0 {\n        query = string.substr(s, q_idx + 1, len(s))\n        s = string.substr(s, 0, q_idx)\n    }\n\n    # Host & Port vs Path\n    let slash_idx = string.index_of(s, \"/\")\n    let host_part = s\n    if slash_idx >= 0 {\n        host_part = string.substr(s, 0, slash_idx)\n        path = string.substr(s, slash_idx, len(s))\n    } else {\n        path = \"/\"\n    }\n\n    let colon_idx = string.index_of(host_part, \":\")\n    if colon_idx >= 0 {\n        host = string.substr(host_part, 0, colon_idx)\n        let port_str = string.substr(host_part, colon_idx + 1, len(host_part))\n        port = string.tonum(port_str)\n        if port == nullx { port = 0 }\n    } else {\n        host = host_part\n    }\n\n    return newx URL(scheme, host, port, path, query, fragment)\n}\n";

