static MxValue aot_build_url(void) {
    static MxValue cache = {0};
    if (cache.tag != MX_NULL) return cache;
    MxValue prog = aot_mk_node("Program", 1);
    MxArray *body_arr = mx_arr_new(9LL);
    body_arr->v[0] = aot_url_stmt_0();
    body_arr->v[1] = aot_url_stmt_1();
    body_arr->v[2] = aot_url_stmt_2();
    body_arr->v[3] = aot_url_stmt_3();
    body_arr->v[4] = aot_url_stmt_4();
    body_arr->v[5] = aot_url_stmt_5();
    body_arr->v[6] = aot_url_stmt_6();
    body_arr->v[7] = aot_url_stmt_7();
    body_arr->v[8] = aot_url_stmt_8();
    aot_set_field(prog, "body", aot_box_arr(body_arr));
    cache = prog;
    return prog;
}

