const char *mx_aot_get_source(const char *name) {
    if (!name) return NULL;
    size_t count = sizeof(g_aot_entries) / sizeof(g_aot_entries[0]);
    for (size_t i = 0; i < count; i++) {
        if (strcmp(g_aot_entries[i].name, name) == 0)
            return g_aot_entries[i].source;
    }
    return NULL;
}

MxValue mx_aot_get_prog(const char *name) {
    if (!name) return mx_null();
    size_t count = sizeof(g_aot_entries) / sizeof(g_aot_entries[0]);
    for (size_t i = 0; i < count; i++) {
        if (strcmp(g_aot_entries[i].name, name) == 0)
            return g_aot_entries[i].build_prog();
    }
    return mx_null();
}
